body.script:
//
(function() {
  'use strict';

  // 1. Toast Notification Helper
  function showToast(msg, icon) {
    var toast = document.getElementById('mosafa-toast');
    var toastMsg = document.getElementById('mosafa-toast-msg');
    var toastIcon = document.getElementById('mosafa-toast-icon');
    if (!toast || !toastMsg) return;
    toastMsg.innerText = msg;
    if (toastIcon && icon) toastIcon.innerText = icon;
    toast.classList.add('show');
    setTimeout(function() {
      toast.classList.remove('show');
    }, 2800);
  }
  window.showMoSaFaToast = showToast;

  // Floating Particles Animation (Matching React App)
  (function initParticles() {
    var canvas = document.getElementById('floatingCanvas');
    if (!canvas) return;
    var ctx = canvas.getContext('2d');
    if (!ctx) return;

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    resize();
    window.addEventListener('resize', resize);

    var particles = [];
    for (var i = 0; i < 22; i++) {
      particles.push({
        x: Math.random() * window.innerWidth,
        y: Math.random() * window.innerHeight,
        size: Math.random() * 3 + 1.5,
        speedY: Math.random() * 0.45 + 0.2,
        speedX: (Math.random() - 0.5) * 0.25,
        opacity: Math.random() * 0.16 + 0.05
      });
    }

    function animate() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      particles.forEach(function(p) {
        p.y -= p.speedY;
        p.x += p.speedX;
        if (p.y < -15) {
          p.y = canvas.height + 15;
          p.x = Math.random() * canvas.width;
        }
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(244, 63, 94, ' + p.opacity + ')';
        ctx.fill();
      });
      requestAnimationFrame(animate);
    }
    animate();
  })();

  // Set Year
  var yElem = document.getElementById('current-year');
  if (yElem) yElem.innerText = new Date().getFullYear();

  // 2. All 18 Tools Registry (Matching Screenshot 1 & App.tsx)
  var TOOLS = [
    {
      id: 'love-test',
      title: 'প্রেম টেস্ট (Love Test)',
      badge: '🔥 ভাইরাল টেস্ট',
      badgeColor: 'bg-rose-50 text-rose-600 border-rose-200',
      category: 'entertainment',
      iconBg: 'from-rose-500 to-pink-600',
      icon: '<svg class="w-6 h-6 fill-white text-white" viewBox="0 0 24 24" fill="currentColor" stroke="currentColor" stroke-width="2"><path d="M19 14c1.49-1.46 3-3.21 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.76 0-3 .5-4.5 2-1.5-1.5-2.74-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4.05 3 5.5l7 7Z"/></svg>',
      description: 'দুজনের বয়স, গায়ের রং, পারিবারিক সম্মতি, বাস্তব প্রশ্ন ও স্বভাব যাচাই করে সম্পর্কের গভীরতা ও ভবিষ্যৎ উদ্দেশ্য নির্ণয় করুন। সনদপত্র ডাউনলোড সুবিধা সহ!',
      deviceTag: '📱💻 কম্পিউটার + মোবাইল ভার্সন',
