    html += '<button type="button" class="cat-pill px-3.5 py-1.5 rounded-xl transition cursor-pointer bg-white border border-slate-200 text-slate-700 hover:bg-slate-100" data-cat="typing">⌨️ টাইপিং ও কন্টেন্ট</button>';
    html += '<button type="button" class="cat-pill px-3.5 py-1.5 rounded-xl transition cursor-pointer bg-white border border-slate-200 text-slate-700 hover:bg-slate-100" data-cat="calculator">🔢 হিসাব, জার্নি ও ক্যালকুলেটর</button>';
