      html += '<p class="text-xs text-slate-600 mt-2 leading-relaxed">' + tool.description + '</p>';
      html += '</div>';

      // Signature "টুল শুরু করুন 🚀" Gradient Button
      html += '<div class="pt-5 mt-4 border-t border-slate-100 flex items-center gap-2">';
      html += '<div class="w-full py-3 px-4 rounded-xl bg-gradient-to-r from-rose-500 via-pink-600 to-indigo-600 hover:from-rose-600 hover:to-indigo-700 text-white font-bold text-xs sm:text-sm shadow-md shadow-rose-200 text-center flex items-center justify-center gap-2 transition active:scale-95 pointer-events-none">';
      html += '<span>⚡</span>';
      html += '<span>টুল শুরু করুন 🚀</span>';
      html += '</div>';
      html += '</div>';

      html += '</div>';
