    html += '<p class="text-xs text-slate-500 mt-1">অন্য কোনো কি-ওয়ার্ড দিয়ে খুঁজে দেখুন অথবা ফিল্টার পরিবর্তন করুন।</p>';
    html += '</div>';

    // Feature Highlights Bar (Matching Screenshot 1)
    html += '<div class="mt-12 bg-white rounded-3xl p-6 sm:p-8 border border-slate-200/90 shadow-sm grid grid-cols-2 md:grid-cols-4 gap-6 text-center">';
    html += '<div>';
    html += '<div class="text-2xl sm:text-3xl font-extrabold text-rose-500 mb-1 flex items-center justify-center gap-1"><span>✅</span><span>১০০%</span></div>';
    html += '<div class="text-xs font-bold text-slate-800">সম্পূর্ণ ফ্রি</div>';
