    html += '</div>';

    html += '<div>';
    html += '<div class="text-2xl sm:text-3xl font-extrabold text-indigo-500 mb-1 flex items-center justify-center gap-1"><span>⚡</span><span>দ্রুত</span></div>';
    html += '<div class="text-xs font-bold text-slate-800">ইনস্ট্যান্ট লোডিং</div>';
    html += '<p class="text-[11px] text-slate-500 mt-0.5">হালকা ও অপটিমাইজড</p>';
    html += '</div>';

    html += '<div>';
    html += '<div class="text-2xl sm:text-3xl font-extrabold text-emerald-500 mb-1 flex items-center justify-center gap-1"><span>🔒</span><span>নিরাপদ</span></div>';
    html += '<div class="text-xs font-bold text-slate-800">ডাটা সেভ হয় না</div>';
    html += '<p class="text-[11px] text-slate-500 mt-0.5">সম্পূর্ণ ক্লায়েন্ট সাইড</p>';
    html += '</div>';

    html += '<div>';
    html += '<div class="text-2xl sm:text-3xl font-extrabold text-amber-500 mb-1 flex items-center justify-center gap-1"><span>📱</span><span>রেসপনসিভ</span></div>';
    html += '<div class="text-xs font-bold text-slate-800">মোবাইল ও পিসি</div>';
    html += '<p class="text-[11px] text-slate-500 mt-0.5">সব ডিভাইসে কাজ করে</p>';
