    html += '</section>';

    root.innerHTML = html;

    // Filter Logic
    function filterTools() {
      var searchInput = document.getElementById('hub-search-input');
      var q = searchInput ? searchInput.value.toLowerCase().trim() : '';

      // Secret code trigger ALL_OK_15
      if (q.toUpperCase() === 'ALL_OK_15') {
        navigateTo('golpo-ghor');
        showToast('🔐 সিক্রেট কোড অ্যাক্টিভেটেড (ALL_OK_15): গল্পের ঘরে আপনাকে সরাসরি নিয়ে আসা হয়েছে!', '📚');
        return;
      }

      var cards = document.querySelectorAll('#tools-grid-container .tool-card');
      var visibleCount = 0;

      cards.forEach(function(card, idx) {
        var tool = TOOLS[idx];
        if (!tool) return;

        var matchesCategory = (currentCategory === 'all' || tool.category === currentCategory);
        var matchesSearch = !q ||
          tool.title.toLowerCase().indexOf(q) !== -1 ||
          tool.description.toLowerCase().indexOf(q) !== -1 ||
          tool.keywords.some(function(k) { return k.toLowerCase().indexOf(q) !== -1; });

        if (matchesCategory && matchesSearch) {
          card.style.display = 'flex';
          visibleCount++;
        } else {
          card.style.display = 'none';
        }
      });

      var noTools = document.getElementById('no-tools-found');
      if (noTools) {
        if (visibleCount === 0) {
          noTools.classList.remove('hidden');
        } else {
          noTools.classList.add('hidden');
        }
      }
    }

    // Category button click handlers
    var catButtons = document.querySelectorAll('#category-pills-container .cat-pill');
    catButtons.forEach(function(btn) {
      btn.addEventListener('click', function() {
        catButtons.forEach(function(b) {
          b.className = 'cat-pill px-3.5 py-1.5 rounded-xl transition cursor-pointer bg-white border border-slate-200 text-slate-700 hover:bg-slate-100';
        });
        btn.className = 'cat-pill px-3.5 py-1.5 rounded-xl transition cursor-pointer bg-slate-900 text-white shadow-xs';
        currentCategory = btn.getAttribute('data-cat');
        filterTools();
      });
    });

    // Search input listener
    var searchInput = document.getElementById('hub-search-input');
    if (searchInput) {
      searchInput.addEventListener('input', filterTools);
    }
  }

  // 5. Render Standalone Tools
  function renderTool(toolId) {
    var root = document.getElementById('mosafa-app-root');
    if (!root) return;

