    var KNOWN_DIST = {
      dhaka: { chittagong: 250, sylhet: 240, 'coxs-bazar': 400, rajshahi: 245, khulna: 220, bogura: 198, barishal: 180, rangpur: 305, mymensingh: 120, cumilla: 98, kuakata: 295, jessore: 195, kushtia: 215, dinajpur: 360, feni: 150, noakhali: 165, tangail: 88, faridpur: 110, pabna: 155, sirajganj: 135 },
      chittagong: { dhaka: 250, 'coxs-bazar': 150, sylhet: 375, cumilla: 152, feni: 100, noakhali: 140 },
      'mirpur-10': { motijheel: 15, sayedabad: 19, uttara: 15 },
