    function getDistance(from, to) {
      if (from === to) return 0;
      if (KNOWN_DIST[from] && KNOWN_DIST[from][to]) return KNOWN_DIST[from][to];
      if (KNOWN_DIST[to] && KNOWN_DIST[to][from]) return KNOWN_DIST[to][from];
      return 185; // realistic default
    }

    function checkToll(from, to) {
      var south = ['khulna', 'barishal', 'kuakata', 'jessore', 'faridpur', 'kushtia'];
      var north = ['rajshahi', 'bogura', 'rangpur', 'dinajpur', 'pabna', 'sirajganj'];
      if ((from === 'dhaka' && south.indexOf(to) !== -1) || (to === 'dhaka' && south.indexOf(from) !== -1)) {
        return { hasToll: true, name: 'পদ্মা সেতু এক্সপ্রেসওয়ে', toll: 50 };
      }
      if ((from === 'dhaka' && north.indexOf(to) !== -1) || (to === 'dhaka' && north.indexOf(from) !== -1)) {
        return { hasToll: true, name: 'বঙ্গবন্ধু যমুনা সেতু', toll: 40 };
      }
      return { hasToll: false, name: '', toll: 0 };
    }

    function generateFares(fromId, toId) {
