    function render() {
      var fromObj = LOCATIONS.find(function(l) { return l.id === state.origin; }) || { name: state.origin };
      var toObj = LOCATIONS.find(function(l) { return l.id === state.destination; }) || { name: state.destination };
      var dist = getDistance(state.origin, state.destination);
      var toll = checkToll(state.origin, state.destination);

      var allFares = generateFares(state.origin, state.destination);

      // Filtering with GUARANTEED NON-EMPTY ACTIVE FALLBACK
      var filtered = allFares.slice();

      if (state.busType !== 'all') {
        var byType = filtered.filter(function(f) { return f.busType === state.busType; });
        if (byType.length > 0) filtered = byType;
      }
      if (state.serviceClass !== 'all') {
        var byClass = filtered.filter(function(f) { return f.serviceClass === state.serviceClass; });
        if (byClass.length > 0) filtered = byClass;
      }
      if (state.operator !== 'all') {
        var byOp = filtered.filter(function(f) { return f.id === state.operator; });
        if (byOp.length > 0) filtered = byOp;
      }
      if (state.filterTab === 'non-ac') {
        var nonAc = filtered.filter(function(f) { return f.serviceClass === 'non-ac'; });
        if (nonAc.length > 0) filtered = nonAc;
      } else if (state.filterTab === 'ac') {
        var ac = filtered.filter(function(f) { return f.serviceClass !== 'non-ac'; });
        if (ac.length > 0) filtered = ac;
      }

      // Sort
      filtered.sort(function(a, b) {
        if (state.sortBy === 'fare-asc') return a.fareAmount - b.fareAmount;
        if (state.sortBy === 'fare-desc') return b.fareAmount - a.fareAmount;
        return a.operatorName.localeCompare(b.operatorName, 'bn');
      });

      var lowest = Math.min.apply(null, filtered.map(function(f) { return f.fareAmount; }));

      var html = '';

      // Header Banner (Authentic Bus Illustration from Screenshot)
      html += '<div class="bg-gradient-to-b from-sky-50 via-white to-slate-50 rounded-3xl p-6 sm:p-10 border border-sky-100 shadow-sm mb-6 text-center">';
      html += '<div class="w-full max-w-md mx-auto mb-2">';
      html += '<svg viewBox="0 0 520 180" fill="none" xmlns="http://www.w3.org/2000/svg" class="w-full h-auto max-h-32 mx-auto">';
      html += '<rect x="10" y="150" width="500" height="8" rx="4" fill="#cbd5e1" />';
      html += '<line x1="40" y1="154" x2="100" y2="154" stroke="#ffffff" stroke-width="3" stroke-dasharray="10 10" />';
      html += '<line x1="160" y1="154" x2="360" y2="154" stroke="#ffffff" stroke-width="3" stroke-dasharray="10 10" />';
      html += '<line x1="420" y1="154" x2="480" y2="154" stroke="#ffffff" stroke-width="3" stroke-dasharray="10 10" />';
      html += '<ellipse cx="260" cy="154" rx="200" ry="8" fill="#0f172a" fill-opacity="0.12" />';
      html += '<path d="M70 140 H450 C465 140 475 130 475 110 V65 C475 40 455 35 430 35 H95 C75 35 60 48 55 70 L45 115 C42 130 52 140 70 140 Z" fill="url(#busBodyGradient)" />';
      html += '<rect x="170" y="24" width="160" height="13" rx="6" fill="#e2e8f0" stroke="#0284c7" stroke-width="2" />';
      html += '<path d="M58 80 H465 V60 C465 52 458 48 440 48 H95 C78 48 68 55 65 65 Z" fill="#0f172a" fill-opacity="0.88" />';
      html += '<rect x="75" y="52" width="55" height="24" rx="3" fill="#38bdf8" fill-opacity="0.5" />';
      html += '<rect x="138" y="52" width="60" height="24" rx="3" fill="#38bdf8" fill-opacity="0.4" />';
      html += '<rect x="206" y="52" width="60" height="24" rx="3" fill="#38bdf8" fill-opacity="0.4" />';
      html += '<rect x="274" y="52" width="60" height="24" rx="3" fill="#38bdf8" fill-opacity="0.4" />';
      html += '<rect x="342" y="52" width="60" height="24" rx="3" fill="#38bdf8" fill-opacity="0.4" />';
      html += '<rect x="410" y="52" width="45" height="24" rx="3" fill="#38bdf8" fill-opacity="0.5" />';
      html += '<path d="M45 105 Q200 95 470 112 L470 122 Q200 105 45 115 Z" fill="#ef4444" />';
