      html += '<button type="button" class="busfare-tab px-3 py-1.5 rounded-lg ' + (state.filterTab === 'ac' ? 'bg-white text-slate-900 shadow-xs' : 'text-slate-600') + '" data-tab="ac">এসি ও স্লিপার</button>';
