      { title: 'মোট ব্যবহৃত ইউনিট (kWh)', hexing: '802 বা 01', inhemeter: '802 বা 01', wasion: '802', sanxing: '802', holley: '01', note: 'মিটার চালু হওয়ার পর থেকে মোট কত ইউনিট বিদ্যুৎ ব্যবহার হয়েছে।' },
      { title: 'মিটার নম্বর (Meter ID)', hexing: '804 বা 04', inhemeter: '804 বা 100', wasion: '804', sanxing: '804', holley: '04', note: 'আপনার প্রিপেইড মিটারের ১১ বা ১২ ডিজিটের আইডি নম্বর।' },
      { title: 'সর্বশেষ রিচার্জ টোকেন কোড', hexing: '813 বা 814', inhemeter: '813', wasion: '813', sanxing: '813', holley: '813', note: 'সর্বশেষ যে ২০ ডিজিটের রিচার্জ টোকেন দেওয়া হয়েছিল তা প্রদর্শন করবে।' },
      { title: 'লাইভ ভোল্টেজ (Volt)', hexing: '805', inhemeter: '805 বা 08', wasion: '805', sanxing: '805', holley: '08', note: 'বর্তমানে লাইন ভোল্টেজ (সাধারণত ২১০-২৩০ ভোল্ট থাকা স্বাভাবিক)।' },
