      html += '<h2 class="text-2xl sm:text-4xl font-black">প্রিপেইড মিটার সহকারী</h2>';
      html += '<p class="text-xs sm:text-sm text-emerald-100">সকল বিদ্যুৎ বিতরণ কোম্পানির মিটারের জরুরি শর্ট কোড, রিচার্জ হিসাব, ব্যালেন্স রানওয়ে ক্যালকুলেটর ও সমস্যার সমাধান।</p>';
      html += '</div>';
      html += '<div class="absolute right-4 bottom-2 text-8xl opacity-15 pointer-events-none">⚡</div>';
      html += '</div>';

      // Navigation Tabs
      html += '<div class="flex items-center gap-2 mb-6 overflow-x-auto pb-1">';
      html += '<button type="button" class="meter-tab-btn px-4 py-2.5 rounded-2xl text-xs font-extrabold transition shrink-0 ' + (state.tab === 'codes' ? 'bg-emerald-600 text-white shadow-md' : 'bg-white border border-slate-200 text-slate-700') + '" data-tab="codes">📋 জরুরি শর্ট কোড</button>';
      html += '<button type="button" class="meter-tab-btn px-4 py-2.5 rounded-2xl text-xs font-extrabold transition shrink-0 ' + (state.tab === 'calc' ? 'bg-emerald-600 text-white shadow-md' : 'bg-white border border-slate-200 text-slate-700') + '" data-tab="calc">🧮 রিচার্জ হিসাব ক্যালকুলেটর</button>';
      html += '<button type="button" class="meter-tab-btn px-4 py-2.5 rounded-2xl text-xs font-extrabold transition shrink-0 ' + (state.tab === 'runway' ? 'bg-emerald-600 text-white shadow-md' : 'bg-white border border-slate-200 text-slate-700') + '" data-tab="runway">⏳ ব্যালেন্স রানওয়ে (কত দিন চলবে)</button>';
      html += '<button type="button" class="meter-tab-btn px-4 py-2.5 rounded-2xl text-xs font-extrabold transition shrink-0 ' + (state.tab === 'guide' ? 'bg-emerald-600 text-white shadow-md' : 'bg-white border border-slate-200 text-slate-700') + '" data-tab="guide">📱 রিচার্জ নিয়ম ও সমাধান</button>';
      html += '</div>';

      // TAB 1: CODES
      if (state.tab === 'codes') {
