        html += '<select id="meter-utility-select" class="w-full px-3 py-2.5 rounded-xl border border-slate-300 bg-white text-xs font-bold focus:ring-2 focus:ring-emerald-500">';
        UTILITIES.forEach(function(u) {
          html += '<option value="' + u.id + '" ' + (u.id === state.utility ? 'selected' : '') + '>' + u.name + '</option>';
        });
        html += '</select></div>';

        // Brand Select
        html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">মিটারের প্রস্তুতকারক / ব্র‍্যান্ড</label>';
        html += '<select id="meter-brand-select" class="w-full px-3 py-2.5 rounded-xl border border-slate-300 bg-white text-xs font-bold focus:ring-2 focus:ring-emerald-500">';
        html += '<option value="hexing" ' + (state.brand === 'hexing' ? 'selected' : '') + '>Hexing (হেক্সিং প্রিপেইড মিটার)</option>';
        html += '<option value="inhemeter" ' + (state.brand === 'inhemeter' ? 'selected' : '') + '>Inhemeter (ইনহিমিটার)</option>';
        html += '<option value="wasion" ' + (state.brand === 'wasion' ? 'selected' : '') + '>Wasion (ওয়াশন স্মার্ট মিটার)</option>';
        html += '<option value="sanxing" ' + (state.brand === 'sanxing' ? 'selected' : '') + '>Sanxing (সানক্সিং মিটার)</option>';
        html += '<option value="holley" ' + (state.brand === 'holley' ? 'selected' : '') + '>Holley (হলি মিটার)</option>';
        html += '</select></div>';
        html += '</div>';

        // Helpline strip
        html += '<div class="p-3 rounded-xl bg-emerald-50 border border-emerald-200 text-xs text-emerald-900 font-bold flex items-center justify-between mb-5">';
        html += '<span>📞 ' + utilObj.short + ' গ্রাহক সেবা হেল্পলাইন: <strong>' + utilObj.helpline + '</strong></span>';
        html += '<span class="text-[11px] text-emerald-700">২৪ ঘণ্টা সচল</span>';
        html += '</div>';

        // Codes Grid
        html += '<div class="grid grid-cols-1 sm:grid-cols-2 gap-4">';
        SHORT_CODES.forEach(function(c) {
          var code = c[state.brand] || c.hexing;
          html += '<div class="p-4 rounded-2xl border border-slate-200 bg-slate-50/70 hover:bg-white hover:border-emerald-300 hover:shadow-sm transition flex flex-col justify-between">';
          html += '<div>';
          html += '<div class="flex items-center justify-between mb-1.5">';
          html += '<span class="text-xs font-black text-slate-800">' + c.title + '</span>';
          html += '<button type="button" class="copy-code-btn px-2.5 py-1 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white font-extrabold text-xs transition" data-code="' + code + '">কপি 📋</button>';
          html += '</div>';
          html += '<div class="my-2 p-2 rounded-xl bg-white border border-slate-200 text-center">';
          html += '<span class="text-xl font-black text-emerald-700 tracking-wider font-mono">' + code + '</span>';
          html += '<span class="block text-[10px] text-slate-400 mt-0.5">টাইপ করে Enter/নীল বাটন চাপুন</span>';
          html += '</div>';
          html += '<p class="text-[11px] text-slate-500 leading-relaxed">' + c.note + '</p>';
          html += '</div></div>';
        });
        html += '</div>';

        html += '</div>';
      }

      // TAB 2: CALCULATOR
      if (state.tab === 'calc') {
        var tk = state.rechargeTk;
        var vat = Math.round(tk * 0.05 * 100) / 100; // 5% VAT
        var demand = 84; // Avg demand charge 2kW
        var rent = 40; // Meter rent
        var rebate = Math.round(tk * 0.01 * 100) / 100; // 1% rebate online
        var net = Math.max(0, Math.round((tk - vat - demand - rent + rebate) * 100) / 100);
        var units = Math.round((net / 7.34) * 10) / 10; // Approx rate Tk 7.34/unit

        html += '<div class="bg-white rounded-3xl p-5 sm:p-7 border border-slate-200/90 shadow-sm mb-6 max-w-xl mx-auto">';
        html += '<h3 class="text-lg font-black text-slate-800 mb-1">রিচার্জ কর্তন ও ইউনিট হিসাব</h3>';
        html += '<p class="text-xs text-slate-500 mb-5">প্রিপেইড মিটারে রিচার্জ করলে কত টাকা কর্তন হয় এবং কত ইউনিট বিদ্যুৎ পাবেন তা সহজে জেনে নিন।</p>';

        html += '<div class="mb-5"><label class="block text-xs font-bold text-slate-700 mb-1">রিচার্জের পরিমাণ (টাকা)</label>';
        html += '<input type="number" id="calc-tk-input" value="' + tk + '" class="w-full px-4 py-3 rounded-xl border border-slate-300 text-base font-black text-slate-900 focus:ring-2 focus:ring-emerald-500" />';
        html += '</div>';

        html += '<div class="space-y-2.5 p-4 rounded-2xl bg-slate-50 border border-slate-200 text-xs mb-5">';
        html += '<div class="flex justify-between font-bold text-slate-700"><span>প্রবেশকৃত টাকা:</span><span>৳' + tk + '</span></div>';
        html += '<div class="flex justify-between text-rose-600 font-bold"><span>(-) ভ্যাট (৫%):</span><span>৳' + vat + '</span></div>';
        html += '<div class="flex justify-between text-rose-600 font-bold"><span>(-) ডিমান্ড চার্জ (২ কিলোওয়াট):</span><span>৳' + demand + '</span></div>';
        html += '<div class="flex justify-between text-rose-600 font-bold"><span>(-) মিটার ভাড়া:</span><span>৳' + rent + '</span></div>';
        html += '<div class="flex justify-between text-emerald-600 font-bold"><span>(+) অনলাইন রিবেট (১%):</span><span>৳' + rebate + '</span></div>';
        html += '<div class="pt-2 border-t border-slate-200 flex justify-between font-black text-sm text-slate-900"><span>বিদ্যুৎ ক্রয়ের অবশিষ্ট টাকা:</span><span>৳' + net + '</span></div>';
        html += '</div>';

        html += '<div class="p-4 rounded-2xl bg-emerald-600 text-white text-center shadow-md">';
        html += '<span class="text-xs font-bold text-emerald-100 block">আনুমানিক ক্রয়কৃত বিদ্যুৎ</span>';
        html += '<span class="text-3xl font-black">' + units + ' ইউনিট (kWh)</span>';
        html += '<span class="text-[11px] text-emerald-100 block mt-1">গড় রেট ৳৭.৩৪/ইউনিট (স্ল্যাব-৩ ভিত্তি) হিসেবে হিসাবকৃত</span>';
        html += '</div>';

        html += '</div>';
      }

      // TAB 3: RUNWAY
      if (state.tab === 'runway') {
        var bal = state.runwayBalance;
        var daily = Math.max(1, state.runwayDaily);
        var days = Math.floor(bal / daily);
        var hours = Math.round(((bal / daily) - days) * 24);

        html += '<div class="bg-white rounded-3xl p-5 sm:p-7 border border-slate-200/90 shadow-sm mb-6 max-w-xl mx-auto">';
        html += '<h3 class="text-lg font-black text-slate-800 mb-1">ব্যালেন্স রানওয়ে ক্যালকুলেটর</h3>';
        html += '<p class="text-xs text-slate-500 mb-5">মিটারে থাকা বর্তমান টাকায় কত দিন বিদ্যুৎ চলবে তা হিসাব করুন।</p>';

        html += '<div class="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-5">';
        html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">বর্তমান ব্যালেন্স (টাকা)</label>';
        html += '<input type="number" id="runway-bal-input" value="' + bal + '" class="w-full px-3 py-2.5 rounded-xl border border-slate-300 font-black text-slate-900" /></div>';
        html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">দৈনিক গড় খরচ (টাকা)</label>';
        html += '<input type="number" id="runway-daily-input" value="' + daily + '" class="w-full px-3 py-2.5 rounded-xl border border-slate-300 font-black text-slate-900" /></div>';
        html += '</div>';

        html += '<div class="p-6 rounded-2xl bg-gradient-to-br from-emerald-600 to-teal-700 text-white text-center shadow-md space-y-1">';
        html += '<span class="text-xs font-bold text-emerald-100">আপনার বিদ্যুৎ চলবে প্রায়</span>';
        html += '<div class="text-3xl sm:text-4xl font-black">' + days + ' দিন ' + hours + ' ঘণ্টা</div>';
        html += '<span class="text-xs text-emerald-100 block pt-1">জরুরি ব্যালেন্স শূন্য হওয়ার পূর্বেই রিচার্জ করার পরামর্শ দেওয়া হচ্ছে।</span>';
        html += '</div>';

        html += '</div>';
      }

      // TAB 4: GUIDES & TROUBLESHOOT
      if (state.tab === 'guide') {
        html += '<div class="grid grid-cols-1 md:grid-cols-2 gap-4">';

        // Guide 1: bKash recharge
        html += '<div class="bg-white rounded-3xl p-5 border border-slate-200/90 space-y-3">';
        html += '<h4 class="text-base font-black text-slate-800">📱 বিকাশ (bKash) দিয়ে রিচার্জ</h4>';
        html += '<ol class="text-xs text-slate-600 space-y-1.5 list-decimal list-inside">';
        html += '<li>বিকাশ অ্যাপে লগইন করে <strong>Pay Bill</strong> সিলেক্ট করুন।</li>';
        html += '<li><strong>Electricity (বিদ্যুৎ)</strong> অপশন বেছে নিন।</li>';
        html += '<li>আপনার মিটার কোম্পানি (যেমন DESCO Prepaid) নির্বাচন করুন।</li>';
        html += '<li>মিটার নম্বর ও টাকার পরিমাণ দিন এবং পিন দিয়ে বিল সম্পন্ন করুন।</li>';
        html += '<li>এসএমএসে প্রাপ্ত ২০ ডিজিটের টোকেন মিটারের বোতাম চেপে প্রবেশ করান।</li>';
        html += '</ol></div>';

        // Guide 2: Nagad recharge
        html += '<div class="bg-white rounded-3xl p-5 border border-slate-200/90 space-y-3">';
        html += '<h4 class="text-base font-black text-slate-800">📱 নগদ (Nagad) দিয়ে রিচার্জ</h4>';
        html += '<ol class="text-xs text-slate-600 space-y-1.5 list-decimal list-inside">';
        html += '<li>নগদ অ্যাপে <strong>বিল পে</strong> অপশনে যান।</li>';
        html += '<li>বিদ্যুৎ সেকশনে গিয়ে কোম্পানি নির্বাচন করুন।</li>';
        html += '<li>মিটার নম্বর দিয়ে রিচার্জের টাকা পরিশোধ করুন।</li>';
        html += '<li>টোকেন নম্বর আসলে মিটারে ইনপুট দিয়ে নীল/Enter চাপুন।</li>';
        html += '</ol></div>';

        // Troubleshoot 1: Token Reject
        html += '<div class="bg-white rounded-3xl p-5 border border-slate-200/90 space-y-2">';
        html += '<h4 class="text-base font-black text-rose-700">⚠️ Token Reject বা রিজেক্ট সমস্যা</h4>';
        html += '<p class="text-xs text-slate-600 leading-relaxed">টোকেন রিজেক্ট হলে সাধারণত কোনো একটি ডিজিট ভুল চাপার কারণে হয়। মিটারের লাল/Cancel বাটন চেপে স্ক্রিন ক্লিয়ার করুন এবং ধীরেসুস্থে ২০টি সংখ্যা আবার টাইপ করে নীল/Enter বাটন চাপুন। পরপর তিনবার ভুল হলে ১৫ মিনিট অপেক্ষা করে আবার চেষ্টা করুন।</p>';
        html += '</div>';

        // Troubleshoot 2: Relay Trip
        html += '<div class="bg-white rounded-3xl p-5 border border-slate-200/90 space-y-2">';
        html += '<h4 class="text-base font-black text-amber-700">⚠️ বিদ্যুৎ সংযোগ বিচ্ছিন্ন (Relay Tripped)</h4>';
        html += '<p class="text-xs text-slate-600 leading-relaxed">অনুমোদিত লোডের চেয়ে বেশি যন্ত্রপাতি (যেমন এসি + গিজার + মোটর একসাথে) চললে মিটার স্বয়ংক্রিয়ভাবে বন্ধ হয়ে যায়। ঘরের বড় লোডগুলো বন্ধ করে ৫ মিনিট পর মিটারের 800 বা নীল বাটন ৫ সেকেন্ড চেপে রাখলে সংযোগ পুনঃস্থাপিত হয়।</p>';
        html += '</div>';

        html += '</div>';
      }

      container.innerHTML = html;

      // Attach Tab Listeners
      var tabBtns = document.querySelectorAll('.meter-tab-btn');
      tabBtns.forEach(function(btn) {
        btn.onclick = function() {
          state.tab = btn.getAttribute('data-tab');
          render();
        };
      });

      // Utility Select
      var utilSelect = document.getElementById('meter-utility-select');
      if (utilSelect) {
        utilSelect.onchange = function(e) {
          state.utility = e.target.value;
          render();
        };
      }

      // Brand Select
      var brandSelect = document.getElementById('meter-brand-select');
      if (brandSelect) {
        brandSelect.onchange = function(e) {
          state.brand = e.target.value;
          render();
        };
      }

      // Copy Code Buttons
      var copyBtns = document.querySelectorAll('.copy-code-btn');
      copyBtns.forEach(function(btn) {
        btn.onclick = function() {
          var cd = btn.getAttribute('data-code');
          if (navigator.clipboard) {
            navigator.clipboard.writeText(cd);
          }
          btn.innerText = 'কপি হয়েছে! ✅';
          showToast('কোড ' + cd + ' সফলভাবে কপি হয়েছে! 📋', '⚡');
          setTimeout(function() {
            btn.innerText = 'কপি 📋';
          }, 2000);
        };
      });

      // Calculator input
      var tkInput = document.getElementById('calc-tk-input');
      if (tkInput) {
        tkInput.oninput = function(e) {
          state.rechargeTk = Number(e.target.value) || 0;
          render();
        };
      }

      // Runway inputs
      var balInput = document.getElementById('runway-bal-input');
      var dailyInput = document.getElementById('runway-daily-input');
      if (balInput && dailyInput) {
        balInput.oninput = function(e) {
          state.runwayBalance = Number(e.target.value) || 0;
          render();
        };
        dailyInput.oninput = function(e) {
          state.runwayDaily = Number(e.target.value) || 1;
          render();
        };
      }
    }

    render();
  }

  // ===========================================================================
  // MODULE 3: MoSaFa Golpo Ghor (গল্পের ঘর)
  // ===========================================================================
  function initGolpoGhorModule() {
    var container = document.getElementById('mosafa-golpo-container');
    if (!container) return;

    var STORIES = [
      {
        id: 'kabuliwala',
        title: 'কাবুলিওয়ালা',
        author: 'রবীন্দ্রনাথ ঠাকুর',
        category: 'ক্লাসিক',
        tag: 'রবীন্দ্রনাথের অমর সৃষ্টি',
        content: 'আমার পাঁচ বছর বয়সের ছোট মেয়ে মিনি এক দণ্ড কথা না কহিয়া থাকিতে পারে না। পৃথিবীতে জন্মগ্রহণ করিয়া ভাষা শিক্ষা করিতে সে কেবল একটি বৎসর কাল ব্যয় করিয়াছিল, তাহার পর হইতে যতক্ষণ সে জাগিয়া থাকে এক মুহূর্ত মৌনভাবে নষ্ট করে না। তাহার মা তাহাকে অনেক সময় ধমক দিয়া থামাইয়া দেয়, কিন্তু আমি তাহা পারি না। মিনি চুপ করিয়া থাকিলে কেমন একপ্রকার অস্বাভাভিক দেখিতে হয়, সে আমি বেশিক্ষণ সহ্য করিতে পারি না। এইজন্য আমার সঙ্গে তাহার কথোপকথনটা একটু বেশি মাত্রায় চলে।\n\nএকদিন সকালবেলায় আমার নভেলের সপ্তদশ পরিচ্ছেদে হাত দিয়াছি এমন সময় মিনি আসিয়া আরম্ভ করিয়া দিল, "বাবা, রামদয়াল দরোয়ান কাককে কৌয়া বলছিল, সে কিচ্ছু জানে না। না?"\nআমি তাহাকে পৃথিবীর ভাষাভেদের বিবরণ বুঝিয়ে দিবার পূর্বে সে দ্বিতীয় প্রশ্ন তুলিল, "বাবা, ভোলা বলছিল আকাশে হাতি আছে, সে শুঁড় দিয়ে জল ঢালে, তাই বৃষ্টি হয়! ভোলা কী যে বকে!"\n\nএমন সময়ে সহসা মিনি ঘরের জানালার কাছে ছুটিয়া গেল এবং চিৎকার করিয়া ডাকিতে লাগিল, "কাবুলিওয়ালা, ও কাবুলিওয়ালা!"\nময়লা ঢিলে কাপড় পরা, মাথায় পাগড়ি, পিঠে ঝুলি, হাতে দুই-চারিটি আঙুরের বাক্স— এক লম্বা কাবুলিওয়ালা ধীরপদে পথ দিয়া যাইতেছিল। মিনির ডাক শুনিয়া সে হাসিয়া মুখ ফিরাইল এবং আমাদের বাড়ির দিকে আসিতে লাগিল। মিনি ভয়ার্ত হইয়া ছুটিয়া গিয়া তাহার মার কাছে লুকাইল। তাহার অন্ধবিশ্বাস ছিল ওই ঝুলির ভিতর মানুষের জ্যান্ত ছেলে লুকানো আছে!\n\nকিন্তু কিছুদিন পরেই দেখিলাম সেই বিশালদেহী কাবুলিওয়ালা রহমতের সঙ্গে ছোট্ট মিনির এক অদ্ভূত সখ্য গড়িয়া উঠিয়াছে। রহমত তাহাকে বাদাম-কিসমিস উপহার দিত, আর মিনি খিলখিল করিয়া হাসিয়া গল্প করিত। দেশান্তরী পিতার হৃদয়ে মিনির রূপ ধরিয়া যেন নিজের ফেলে আসা কন্যার স্মৃতিই প্রতিধ্বনিত হইতেছিল।'
      },
      {
        id: 'postmaster',
        title: 'পোস্টমাস্টার',
        author: 'রবীন্দ্রনাথ ঠাকুর',
        category: 'ক্লাসিক',
        tag: 'হৃদয়স্পর্শী ছোটগল্প',
        content: 'উলাপুর গ্রামে পোস্টমাস্টারকে প্রথম কর্মে আসিতে হইয়াছে। গ্রামটি অতি সামান্য। নিকটে একটি নীলকুঠি আছে, তাহারই ম্যানেজারবাবুর চেষ্টায় এই নতুন পোস্টাফিস স্থাপিত হইয়াছে।\n\nআমাদের পোস্টমাস্টার কলিকাতার ছেলে। জলের মাছকে ডাঙায় তুলিলে যেরূপ অবস্থা হয়, এই গণ্ডগ্রামের মধ্যে আসিয়া পোস্টমাস্টারেরও সেইরূপ অবস্থা হইয়াছে। কাজকর্ম বিশেষ কিছুই নাই। সামান্য একটু লিখাপড়া করিতে হয়। এখানকার লোকেদের সঙ্গে তিনি ভালো মিশিতে পারেন না। কলিকাতার ছেলেটি স্থানীয় ভাষায় কথা বলিতে পারে না, এখানকার লোকেরাও তাহাকে শহরের বাবু ভাবিয়া সমীহ করিয়া চলে।\n\nপোস্টমাস্টারের ঘরে একটি অনাথা বালিকা কাজকর্ম করিয়া দিত। তাহার নাম রতন। বয়স বারো-তেরো। রতন তাহার জন্য জল তুলিয়া আনিত, রাঁধিয়া দিত এবং সন্ধ্যাবেলায় পোস্টমাস্টার যখন দাওয়ায় বসিয়া হুকা টানিতেন, তখন রতন মেঝেতে বসিয়া তাহার বাড়ির গল্প শুনিত। পোস্টমাস্টার তাহাকে বর্ণপরিচয় পড়াইতে আরম্ভ করিলেন।\n\nসহসা বর্ষাকালে পোস্টমাস্টার কঠিন জ্বরে পড়িলেন। সেই ঘোর অসুস্থতায় রতন তাহার মায়ের মতোই সেবাযত্ন করিল। আরোগ্য লাভ করিয়া পোস্টমাস্টার কলিকাতায় বদলির আবেদন করিলেন, কিন্তু দরখাস্ত প্রত্যাখ্যাত হওয়ায় তিনি চাকরিতে ইস্তফা দিলেন।\n\nযাইবার সময় রতন অশ্রুসজল চোখে প্রার্থনা করিল, "দাদাবাবু, আমাকে তোমাদের বাড়ি নিয়ে চলো।"\nপোস্টমাস্টার হাসিয়া কহিলেন, "সে কী করে হবে!"\nনৌকায় উঠিয়া যখন পাল তুলিয়া দেওয়া হইল, তখন নদীর কলধ্বনির মধ্যে সেই অনাথা বালিকার কান্নাই যেন পোস্টমাস্টারের হৃদয়ে অবিরাম বাজিয়া উঠিতেছিল।'
      },
      {
        id: 'mahesh',
        title: 'মহেশ',
        author: 'শরৎচন্দ্র চট্টোপাধ্যায়',
        category: 'ক্লাসিক',
        tag: 'সামাজিক ট্র্যাজেডি',
        content: 'কাশীপুর গ্রামের গফুর জোলা। সংসারে তাহার দশ বছরের কন্যা আমিনা এবং পোষা বলদ মহেশ ছাড়া আর কেহই নাই।\n\nঅনাবৃষ্টির বছর। চাষবাস হয় নাই। মহেশকে খাওয়াইবার মতো বিচালি বা ঘাস নাই। গফুর নিজের ঘরের চালের পুরানো খড় খুঁড়িয়া খুঁড়িয়া মহেশকে খাওয়াইত। ক্ষুধায় মহেশ যখন দুর্বল হইয়া উঠিত, গফুর তাহার গায়ে হাত বুলাইয়া বলিত, "মহেশ, তুই আমার ব্যাটা, তোকে যে খেতে দিতে পারি নে রে!"\n\nতর্কতীর্থের জমিতে মহেশ মুখ দেওয়ায় জমিদারের পেয়াদা আসিয়া গফুরকে মারপিট করিল। দারুণ তৃষ্ণায় একফোঁটা জল নাই। মেয়ে আমিনা নদী হইতে শেষ কলসি জল আনিয়াছিল, অসাবধানে সেই কলসির উপর তৃষ্ণার্ত মহেশ মুখ দিতেই কলসি ভাঙিয়া জল মাটিতে মিশিয়া গেল।\n\nউত্তপ্ত রোদ আর ক্ষুধার্ত গফুরের মস্তিষ্ক মুহূর্তের জন্য অন্ধকার হইয়া গেল। সে হাতের কাছে থাকা ভাঙা লাঙলের ফাল তুলিয়া মহেশের মাথায় আঘাত করিয়া বসিল। মহেশ শুধু একবার তাহার প্রভুর দিকে করুণ চোখে চাহিল, তারপর শান্ত হইয়া পড়িয়া রহিল।\n\nগফুর কাঁদিতে কাঁদিতে আল্লাহর দরবারে ফরিয়াদ করিল, "খোদা, যে তোমার বোবা জানোয়ারের খাবার কেড়ে নিয়েছে, তাকে তুমি কোনোদিন ক্ষমা করো না।" সেই রাতেই গফুর আমিনাকে লইয়া চটকলের উদ্দেশে গ্রাম ছাড়িল।'
      }
    ];

    var selectedStory = STORIES[0];

    function render() {
      var html = '';
      html += '<div class="rounded-3xl bg-gradient-to-br from-amber-600 via-rose-700 to-indigo-900 text-white p-6 sm:p-8 shadow-lg mb-6">';
      html += '<h2 class="text-2xl sm:text-4xl font-black">গল্পের ঘর (ডিজিটাল পাঠাগার)</h2>';
      html += '<p class="text-xs sm:text-sm text-amber-100 mt-1">রবীন্দ্রনাথ ও শরৎচন্দ্রের কালজয়ী বাংলা সাহিত্য ও ক্লাসিক ছোটগল্প।</p>';
      html += '</div>';

      html += '<div class="grid grid-cols-1 md:grid-cols-3 gap-6">';

      // Story List Sidebar
      html += '<div class="space-y-3">';
      html += '<h3 class="text-xs font-black text-slate-500 uppercase tracking-wider">গল্পের তালিকা</h3>';
      STORIES.forEach(function(s) {
        var isAct = (s.id === selectedStory.id);
        html += '<button type="button" class="story-select-btn w-full text-left p-4 rounded-2xl border transition ' + (isAct ? 'bg-amber-500 text-white border-amber-600 shadow-md' : 'bg-white border-slate-200 text-slate-800 hover:border-amber-400') + '" data-id="' + s.id + '">';
        html += '<span class="text-[10px] uppercase font-bold block ' + (isAct ? 'text-amber-100' : 'text-slate-400') + '">' + s.author + '</span>';
        html += '<h4 class="text-base font-black leading-tight mt-0.5">' + s.title + '</h4>';
        html += '<span class="text-[11px] font-semibold mt-1 inline-block ' + (isAct ? 'text-amber-100' : 'text-amber-600') + '">' + s.tag + '</span>';
        html += '</button>';
      });
      html += '</div>';

      // Reader Pane
      html += '<div class="md:col-span-2 bg-white rounded-3xl p-6 sm:p-8 border border-slate-200/90 shadow-sm">';
      html += '<div class="border-b border-slate-100 pb-4 mb-5 flex items-start justify-between gap-3">';
      html += '<div>';
      html += '<span class="px-2.5 py-0.5 rounded-md bg-amber-50 text-amber-800 text-xs font-bold border border-amber-200">' + selectedStory.author + '</span>';
      html += '<h3 class="text-2xl font-black text-slate-900 mt-1">' + selectedStory.title + '</h3>';
      html += '</div>';
      html += '<button type="button" id="copy-story-btn" class="px-3 py-1.5 rounded-xl border border-slate-300 text-slate-700 hover:bg-slate-50 text-xs font-bold transition">কপি 📋</button>';
      html += '</div>';

      html += '<div class="prose text-slate-700 text-sm sm:text-base leading-relaxed space-y-4 whitespace-pre-line font-serif">';
      html += selectedStory.content;
      html += '</div>';
      html += '</div>';

      html += '</div>';

      container.innerHTML = html;

      var sBtns = document.querySelectorAll('.story-select-btn');
      sBtns.forEach(function(b) {
        b.onclick = function() {
          var id = b.getAttribute('data-id');
          selectedStory = STORIES.find(function(s) { return s.id === id; }) || STORIES[0];
          render();
        };
      });

      var copyBtn = document.getElementById('copy-story-btn');
      if (copyBtn) {
        copyBtn.onclick = function() {
          if (navigator.clipboard) {
            navigator.clipboard.writeText(selectedStory.title + '\n' + selectedStory.author + '\n\n' + selectedStory.content);
          }
          copyBtn.innerText = 'কপি হয়েছে! ✅';
          showToast('সম্পূর্ণ গল্পটি ক্লিপবোর্ডে কপি হয়েছে! 📖', '📚');
          setTimeout(function() {
            copyBtn.innerText = 'কপি 📋';
          }, 2000);
        };
      }
    }

    render();
  }

  // ===========================================================================
  // MODULE 4: Love Test (প্রেম টেস্ট)
  // ===========================================================================
  function initLoveTestModule() {
    var container = document.getElementById('mosafa-lovetest-container');
    if (!container) return;

    var html = '';
    html += '<div class="max-w-lg mx-auto bg-white rounded-3xl p-6 sm:p-8 border border-slate-200/90 shadow-md text-center">';
    html += '<div class="w-16 h-16 rounded-full bg-rose-50 text-rose-500 mx-auto flex items-center justify-center text-3xl mb-3 shadow-inner">💖</div>';
    html += '<h2 class="text-2xl font-black text-slate-900">প্রেম টেস্ট ও রোমান্স স্কোর</h2>';
    html += '<p class="text-xs text-slate-500 mt-1 mb-6">দুইজনের নাম লিখে ভালোবাসার শতকরা স্কোর ও কম্প্যাটিবিলিটি জানুন।</p>';

    html += '<div class="space-y-4 text-left mb-6">';
    html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">আপনার নাম</label><input type="text" id="love-name1" placeholder="নাম লিখুন..." class="w-full px-4 py-2.5 rounded-xl border border-slate-300 text-xs font-bold focus:ring-2 focus:ring-rose-400" /></div>';
    html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">সঙ্গীর নাম</label><input type="text" id="love-name2" placeholder="সঙ্গীর নাম লিখুন..." class="w-full px-4 py-2.5 rounded-xl border border-slate-300 text-xs font-bold focus:ring-2 focus:ring-rose-400" /></div>';
    html += '</div>';

    html += '<button type="button" id="calc-love-btn" class="w-full py-3 rounded-2xl bg-gradient-to-r from-rose-500 via-pink-600 to-red-600 hover:from-rose-600 hover:to-red-700 text-white font-black text-sm shadow-md transition">ভালোবাসার স্কোর গণনা করুন 💘</button>';

    html += '<div id="love-result-box" class="mt-6 p-6 rounded-2xl bg-rose-50 border border-rose-200 hidden space-y-2">';
    html += '<span class="text-xs font-bold text-rose-600 uppercase tracking-wider block">কম্প্যাটিবিলিটি রেজাল্ট</span>';
    html += '<div id="love-score-display" class="text-5xl font-black text-rose-600">0%</div>';
    html += '<p id="love-message" class="text-xs font-bold text-slate-700 leading-relaxed"></p>';
    html += '</div>';

    html += '</div>';

    container.innerHTML = html;

    var btn = document.getElementById('calc-love-btn');
    if (btn) {
      btn.onclick = function() {
        var n1 = document.getElementById('love-name1').value.trim();
        var n2 = document.getElementById('love-name2').value.trim();
        if (!n1 || !n2) {
          showToast('দয়া করে উভয় ব্যক্তির নাম প্রবেশ করান!', '⚠️');
          return;
        }

        var combined = (n1 + n2).toLowerCase();
        var sum = 0;
        for (var i = 0; i < combined.length; i++) {
          sum += combined.charCodeAt(i);
        }
        var score = 65 + (sum % 34); // Generates between 65% and 98%

        var resBox = document.getElementById('love-result-box');
        var scoreDisp = document.getElementById('love-score-display');
        var msgDisp = document.getElementById('love-message');

        resBox.classList.remove('hidden');
        scoreDisp.innerText = score + '%';

        var comment = 'অসাধারণ জুটি! আপনাদের বোঝাপড়া ও পারস্পরিক শ্রদ্ধা চিরকাল অটুট থাকবে। 💖';
        if (score > 90) comment = 'একান্ত আত্মার বন্ধন! আপনাদের ভালোবাসা যেন আকাশের তারার মতো উজ্জ্বল। 🌟';
        msgDisp.innerText = n1 + ' ও ' + n2 + '-এর সম্পর্ক: ' + comment;

        if (window.confetti) {
          window.confetti({ particleCount: 60, spread: 70, origin: { y: 0.6 } });
        }
        showToast('প্রেম স্কোর সফলভাবে তৈরি হয়েছে! 🎉', '💖');
      };
    }
  }

  // ===========================================================================
  // MODULE 5: Typing Test (টাইপিং টেস্ট)
  // ===========================================================================
  function initTypingTestModule() {
    var container = document.getElementById('mosafa-typing-container');
    if (!container) return;

    var SAMPLE_TEXT = 'বাংলাদেশ আমাদের প্রিয় জন্মভূমি। নদীমাতৃক এই রূপসী বাংলার প্রকৃতি চিরসবুজ ও মনোমুগ্ধকর। এখানে মানুষ অত্যন্ত অতিথি পরায়ণ ও আন্তরিক। বাংলা আমাদের মাতৃভাষা।';

    var html = '';
    html += '<div class="max-w-xl mx-auto bg-white rounded-3xl p-6 sm:p-8 border border-slate-200/90 shadow-md">';
    html += '<h2 class="text-2xl font-black text-slate-900 text-center mb-1">লিপি বাংলা টাইপিং টেস্ট</h2>';
    html += '<p class="text-xs text-slate-500 text-center mb-6">নিচের অনুচ্ছেদটি দেখে হুবহু টাইপ করে আপনার টাইপিং স্পিড পরীক্ষা করুন।</p>';

    html += '<div class="p-4 rounded-2xl bg-slate-50 border border-slate-200 text-slate-800 font-medium text-sm leading-relaxed mb-4 select-none" id="sample-text-box">' + SAMPLE_TEXT + '</div>';

    html += '<textarea id="typing-input" rows="4" placeholder="এখানে দ্রুত টাইপ করা শুরু করুন..." class="w-full p-4 rounded-2xl border border-slate-300 text-sm font-medium focus:ring-2 focus:ring-sky-500 focus:outline-none mb-4"></textarea>';

    html += '<div class="grid grid-cols-3 gap-3 text-center mb-4">';
    html += '<div class="p-3 rounded-xl bg-sky-50 border border-sky-100"><span class="text-[10px] text-slate-500 font-bold block">সময় বাকি</span><span class="text-xl font-black text-sky-700" id="typing-timer">৬০ সে.</span></div>';
    html += '<div class="p-3 rounded-xl bg-emerald-50 border border-emerald-100"><span class="text-[10px] text-slate-500 font-bold block">গতি (WPM)</span><span class="text-xl font-black text-emerald-700" id="typing-wpm">০</span></div>';
    html += '<div class="p-3 rounded-xl bg-purple-50 border border-purple-100"><span class="text-[10px] text-slate-500 font-bold block">অক্ষর সংখ্যা</span><span class="text-xl font-black text-purple-700" id="typing-chars">০</span></div>';
    html += '</div>';

    html += '<button type="button" id="reset-typing-btn" class="w-full py-2.5 rounded-xl border border-slate-300 text-slate-700 hover:bg-slate-100 font-bold text-xs transition">পুনরায় শুরু করুন 🔄</button>';

    html += '</div>';

    container.innerHTML = html;

    var input = document.getElementById('typing-input');
    var timerDisp = document.getElementById('typing-timer');
    var wpmDisp = document.getElementById('typing-wpm');
    var charsDisp = document.getElementById('typing-chars');
    var resetBtn = document.getElementById('reset-typing-btn');

    var timeLeft = 60;
    var timer = null;
    var started = false;

    if (input) {
      input.oninput = function() {
        if (!started) {
          started = true;
          timer = setInterval(function() {
            timeLeft--;
            if (timerDisp) timerDisp.innerText = timeLeft + ' সে.';
            if (timeLeft <= 0) {
              clearInterval(timer);
              input.disabled = true;
              showToast('টাইপিং টেস্ট সম্পন্ন হয়েছে! 🎉', '⌨️');
            }
          }, 1000);
        }

        var text = input.value;
        if (charsDisp) charsDisp.innerText = text.length;

        var words = text.trim().split(/\s+/).filter(Boolean).length;
        var elapsed = (60 - timeLeft) / 60;
        if (elapsed > 0 && wpmDisp) {
          wpmDisp.innerText = Math.round(words / elapsed);
        }
      };
    }

    if (resetBtn) {
      resetBtn.onclick = function() {
        clearInterval(timer);
        initTypingTestModule();
      };
    }
  }

  // ===========================================================================
  // MODULE 6: Age Calculator (বয়স ক্যালকুলেটর)
  // ===========================================================================
  function initAgeCalcModule() {
    var container = document.getElementById('mosafa-age-container');
    if (!container) return;

    var html = '';
    html += '<div class="max-w-md mx-auto bg-white rounded-3xl p-6 sm:p-8 border border-slate-200/90 shadow-md">';
    html += '<h2 class="text-2xl font-black text-slate-900 text-center mb-1">নিখুঁত বয়স ক্যালকুলেটর</h2>';
    html += '<p class="text-xs text-slate-500 text-center mb-6">আপনার জন্মতারিখ নির্বাচন করে সঠিক বয়স ও ভবিষ্যৎ জন্মদিন জানুন।</p>';

    html += '<div class="mb-5"><label class="block text-xs font-bold text-slate-700 mb-1">জন্মতারিখ নির্ধারণ করুন</label>';
    html += '<input type="date" id="age-birth-date" class="w-full px-4 py-3 rounded-xl border border-slate-300 font-bold text-slate-800 focus:ring-2 focus:ring-indigo-500" />';
    html += '</div>';

    html += '<button type="button" id="calc-age-btn" class="w-full py-3 rounded-2xl bg-indigo-600 hover:bg-indigo-700 text-white font-black text-xs sm:text-sm shadow-md transition">বয়স হিসাব করুন ➔</button>';

    html += '<div id="age-result-box" class="mt-6 p-5 rounded-2xl bg-indigo-50 border border-indigo-200 hidden space-y-3">';
    html += '<div class="text-center"><span class="text-xs text-indigo-700 font-bold block">আপনার বর্তমান বয়স</span><span id="age-main-text" class="text-2xl font-black text-indigo-900"></span></div>';
    html += '<div class="grid grid-cols-2 gap-2 text-center text-xs font-bold pt-2 border-t border-indigo-100">';
    html += '<div class="bg-white p-2.5 rounded-xl"><span class="text-[10px] text-slate-400 block">মোট দিন</span><span id="age-total-days" class="text-slate-800"></span></div>';
    html += '<div class="bg-white p-2.5 rounded-xl"><span class="text-[10px] text-slate-400 block">পরবর্তী জন্মদিন</span><span id="age-next-bday" class="text-slate-800"></span></div>';
    html += '</div>';
    html += '</div>';

    html += '</div>';

    container.innerHTML = html;

    var btn = document.getElementById('calc-age-btn');
    if (btn) {
      btn.onclick = function() {
        var input = document.getElementById('age-birth-date').value;
        if (!input) {
          showToast('দয়া করে জন্মতারিখ নির্বাচন করুন!', '⚠️');
          return;
        }

        var birth = new Date(input);
        var now = new Date();

        if (birth > now) {
          showToast('জন্মতারিখ বর্তমান সময়ের চেয়ে বেশি হতে পারে না!', '⚠️');
          return;
        }

        var years = now.getFullYear() - birth.getFullYear();
        var months = now.getMonth() - birth.getMonth();
        var days = now.getDate() - birth.getDate();

        if (days < 0) {
          months--;
          days += 30;
        }
        if (months < 0) {
          years--;
          months += 12;
        }

        var diffTime = Math.abs(now - birth);
        var diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        var resBox = document.getElementById('age-result-box');
        resBox.classList.remove('hidden');

        document.getElementById('age-main-text').innerText = years + ' বছর, ' + months + ' মাস, ' + days + ' দিন';
        document.getElementById('age-total-days').innerText = diffDays + ' দিন';

        // Next birthday
        var nextBday = new Date(now.getFullYear(), birth.getMonth(), birth.getDate());
        if (nextBday < now) {
          nextBday.setFullYear(now.getFullYear() + 1);
        }
        var daysToNext = Math.ceil((nextBday - now) / (1000 * 60 * 60 * 24));
        document.getElementById('age-next-bday').innerText = daysToNext + ' দিন পর';

        showToast('বয়স সফলভাবে হিসাব করা হয়েছে! 🎂', '📅');
      };
    }
  }

  // ===========================================================================
  // MODULE 7: Coin Toss (কয়েন টস)
  // ===========================================================================
  function initCoinTossModule() {
    var container = document.getElementById('mosafa-coin-container');
    if (!container) return;

    var html = '';
    html += '<div class="max-w-md mx-auto bg-white rounded-3xl p-6 sm:p-8 border border-slate-200/90 shadow-md text-center">';
    html += '<h2 class="text-2xl font-black text-slate-900 mb-1">কয়েন টস ও সিদ্ধান্ত গ্রহণ</h2>';
    html += '<p class="text-xs text-slate-500 mb-6">যে কোনো দ্বিধা বা খেলার আগে নিরপেক্ষভাবে টস করুন।</p>';

    html += '<div class="my-8 flex justify-center">';
    html += '<div id="coin-visual" class="w-32 h-32 rounded-full bg-gradient-to-tr from-amber-400 via-yellow-300 to-amber-500 border-4 border-amber-600 flex items-center justify-center text-4xl font-black text-amber-900 shadow-xl transition-all duration-500">🪙</div>';
    html += '</div>';

    html += '<div id="coin-result-text" class="text-lg font-black text-slate-800 mb-6">টস করতে নিচের বাটনে চাপ দিন</div>';

    html += '<button type="button" id="flip-coin-btn" class="w-full py-3 rounded-2xl bg-amber-500 hover:bg-amber-600 text-white font-black text-sm shadow-md transition">কয়েন টস করুন 🪙</button>';

    html += '</div>';

    container.innerHTML = html;

    var btn = document.getElementById('flip-coin-btn');
    var coin = document.getElementById('coin-visual');
    var txt = document.getElementById('coin-result-text');

    if (btn) {
      btn.onclick = function() {
        btn.disabled = true;
        txt.innerText = 'কয়েন বাতাসে ঘুরছে...';
        coin.style.transform = 'rotateY(720deg) scale(1.15)';

        setTimeout(function() {
          var isHead = Math.random() > 0.5;
          coin.style.transform = 'rotateY(0deg) scale(1)';
          coin.innerText = isHead ? 'হেড' : 'টেইল';
          txt.innerText = 'ফলাফল: ' + (isHead ? 'হেড (Head) এসেছে! 🎉' : 'টেইল (Tail) এসেছে! 🎉');
          btn.disabled = false;
          showToast('টস সম্পন্ন হয়েছে! 🪙', isHead ? '👑' : '⭐');
        }, 600);
      };
    }
  }

