  function initStatusHubModule() {
    var container = document.getElementById('mosafa-status-container');
    if (!container) return;

    var STATUS_LIST = [
      { text: 'হৃদয়ের অনুভূতিগুলো যখন ভাষায় প্রকাশ করা যায় না, তখন নীরবতাই সবচেয়ে বড় ভাষা হয়ে দাঁড়ায়।', cat: 'রোমান্টিক' },
      { text: 'ধৈর্য এমন একটি বৃক্ষ, যার শিকড় তিক্ত হলেও ফল অত্যন্ত মিষ্টি।', cat: 'ইসলামিক' },
