      { text: 'মানুষের জীবনের সবচেয়ে বড় জয় হলো নিজের খারাপ সময়ের সাথে লড়াই করে টিকে থাকা।', cat: 'মোটিভেশনাল' },
      { text: 'যে বুঝতে চায় না, তাকে হাজার বুঝিয়েও লাভ নেই। সময়ের চেয়ে বড় শিক্ষক আর কেউ হয় না।', cat: 'বাস্তবতা' }
    ];

    var html = '';
    html += '<div class="rounded-3xl bg-gradient-to-br from-purple-600 via-indigo-700 to-slate-900 text-white p-6 sm:p-8 shadow-lg mb-6">';
    html += '<h2 class="text-2xl sm:text-4xl font-black">বাংলা স্ট্যাটাস ও ক্যাপশন হাব</h2>';
    html += '<p class="text-xs sm:text-sm text-purple-100 mt-1">সোশ্যাল মিডিয়ায় শেয়ার করার মতো বাছাইকৃত চমৎকার স্ট্যাটাস সংগ্রহ।</p>';
    html += '</div>';

    html += '<div class="grid grid-cols-1 sm:grid-cols-2 gap-4">';
    STATUS_LIST.forEach(function(s) {
      html += '<div class="bg-white rounded-3xl p-5 border border-slate-200/90 shadow-xs flex flex-col justify-between">';
      html += '<div class="space-y-3">';
      html += '<span class="px-2.5 py-1 rounded-lg bg-purple-50 text-purple-800 text-[10px] font-black border border-purple-200">' + s.cat + '</span>';
      html += '<p class="text-slate-800 text-sm font-semibold leading-relaxed">“' + s.text + '”</p>';
      html += '</div>';
      html += '<div class="pt-4 mt-4 border-t border-slate-100 flex justify-end">';
      html += '<button type="button" class="copy-status-btn px-3 py-1.5 rounded-xl bg-purple-600 hover:bg-purple-700 text-white font-extrabold text-xs transition" data-text="' + s.text + '">কপি করুন 📋</button>';
      html += '</div></div>';
