  // ===========================================================================
  // MODULE 9: Love Percentage Calculator (কুইক লাভ পারসেন্টেজ)
  // ===========================================================================
  function initLoveCalcModule() {
    var container = document.getElementById('mosafa-lovecalc-container');
    if (!container) return;

    var html = '<div class="max-w-md mx-auto bg-white rounded-3xl p-6 sm:p-8 border border-slate-200/90 shadow-md text-center">';
    html += '<div class="w-16 h-16 rounded-full bg-pink-50 text-pink-500 mx-auto flex items-center justify-center text-3xl mb-3 shadow-inner">💖</div>';
    html += '<h2 class="text-2xl font-black text-slate-900">কুইক লাভ পারসেন্টেজ</h2>';
    html += '<p class="text-xs text-slate-500 mt-1 mb-6">দুজনের নাম লিখে এক ক্লিকে ভালোবাসার শতকরা হার জেনে নিন।</p>';
    html += '<div class="space-y-3 mb-6 text-left">';
    html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">প্রথম ব্যক্তির নাম</label><input type="text" id="lc-name1" placeholder="নাম লিখুন..." class="w-full px-4 py-2.5 rounded-xl border border-slate-300 text-xs font-bold focus:ring-2 focus:ring-pink-400" /></div>';
    html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">দ্বিতীয় ব্যক্তির নাম</label><input type="text" id="lc-name2" placeholder="নাম লিখুন..." class="w-full px-4 py-2.5 rounded-xl border border-slate-300 text-xs font-bold focus:ring-2 focus:ring-pink-400" /></div>';
    html += '</div>';
    html += '<button type="button" id="lc-btn" class="w-full py-3 rounded-2xl bg-gradient-to-r from-pink-500 via-rose-500 to-red-500 hover:from-pink-600 hover:to-red-600 text-white font-black text-sm shadow-md transition">লাভ পারসেন্টেজ বের করুন ✨</button>';
    html += '<div id="lc-res" class="mt-6 p-6 rounded-2xl bg-pink-50 border border-pink-200 hidden space-y-2">';
    html += '<div id="lc-val" class="text-5xl font-black text-pink-600">0%</div>';
    html += '<p id="lc-desc" class="text-xs font-bold text-slate-700"></p>';
    html += '</div></div>';

    container.innerHTML = html;

    var btn = document.getElementById('lc-btn');
    if (btn) {
      btn.onclick = function() {
        var n1 = (document.getElementById('lc-name1').value || '').trim();
        var n2 = (document.getElementById('lc-name2').value || '').trim();
        if (!n1 || !n2) {
          showToast('উভয় ব্যক্তির নাম লিখুন!', '⚠️');
          return;
        }
        var sum = 0;
        var combo = (n1 + n2).toLowerCase();
        for (var i = 0; i < combo.length; i++) sum += combo.charCodeAt(i);
        var pct = 70 + (sum % 29);
        var res = document.getElementById('lc-res');
        res.classList.remove('hidden');
        document.getElementById('lc-val').innerText = pct + '%';
        document.getElementById('lc-desc').innerText = n1 + ' ও ' + n2 + '-এর বোঝাপড়া চমৎকার ও দীর্ঘস্থায়ী!';
        if (window.confetti) window.confetti({ particleCount: 50, spread: 60 });
        showToast('লাভ পারসেন্টেজ তৈরি হয়েছে! 💖', '✨');
      };
    }
  }

  // ===========================================================================
  // MODULE 10: MoSaFa Name Reveal (নামের গোপন গল্প ও অর্থ)
  // ===========================================================================
  function initNameRevealModule() {
    var container = document.getElementById('mosafa-name-container');
    if (!container) return;

    var html = '<div class="max-w-2xl mx-auto bg-white rounded-3xl p-6 sm:p-8 border border-slate-200/90 shadow-md">';
    html += '<div class="text-center mb-6">';
    html += '<div class="w-14 h-14 rounded-2xl bg-gradient-to-tr from-blue-600 to-purple-600 text-white mx-auto flex items-center justify-center text-2xl mb-2 shadow-md">🔮</div>';
    html += '<h2 class="text-2xl font-black text-slate-900">MoSaFa Name Reveal</h2>';
    html += '<p class="text-xs text-slate-500">আপনার নামের গোপন অর্থ, রাশি, শুভ সংখ্যা ও ভবিষ্যৎ ব্যক্তিত্ব উন্মোচন করুন।</p>';
    html += '</div>';

    html += '<div class="grid grid-cols-1 sm:grid-cols-3 gap-3 mb-5">';
    html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">আপনার নাম</label><input type="text" id="nr-name" placeholder="নাম লিখুন (যেমন: আরিফ)" class="w-full px-3 py-2.5 rounded-xl border border-slate-300 text-xs font-bold" /></div>';
    html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">লিঙ্গ</label><select id="nr-gender" class="w-full px-3 py-2.5 rounded-xl border border-slate-300 text-xs font-bold"><option value="পুরুষ">পুরুষ</option><option value="নারী">নারী</option></select></div>';
    html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">জন্ম সাল</label><input type="number" id="nr-year" value="2000" class="w-full px-3 py-2.5 rounded-xl border border-slate-300 text-xs font-bold" /></div>';
    html += '</div>';

    html += '<button type="button" id="nr-btn" class="w-full py-3 rounded-2xl bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white font-black text-sm shadow-md transition">নামের রহস্য উন্মোচন করুন 🔮</button>';

    html += '<div id="nr-res" class="mt-6 space-y-4 hidden">';
    html += '<div class="p-5 rounded-2xl bg-purple-50 border border-purple-200 space-y-2"><h4 class="text-xs font-black text-purple-800 uppercase tracking-wider">অধ্যায় ১: নামের অর্থ ও ব্যক্তিত্ব</h4><p id="nr-c1" class="text-xs text-slate-700 leading-relaxed font-medium"></p></div>';
    html += '<div class="p-5 rounded-2xl bg-blue-50 border border-blue-200 space-y-2"><h4 class="text-xs font-black text-blue-800 uppercase tracking-wider">অধ্যায় ২: শুভ সংখ্যা ও শুভ বর্ণ</h4><p id="nr-c2" class="text-xs text-slate-700 leading-relaxed font-medium"></p></div>';
    html += '<div class="p-5 rounded-2xl bg-emerald-50 border border-emerald-200 space-y-2"><h4 class="text-xs font-black text-emerald-800 uppercase tracking-wider">অধ্যায় ৩: কর্মজীবন ও আর্থিক ভাগ্য</h4><p id="nr-c3" class="text-xs text-slate-700 leading-relaxed font-medium"></p></div>';
    html += '<div class="p-5 rounded-2xl bg-amber-50 border border-amber-200 space-y-2"><h4 class="text-xs font-black text-amber-800 uppercase tracking-wider">অধ্যায় ৪: রাশি ও জীবনধারা</h4><p id="nr-c4" class="text-xs text-slate-700 leading-relaxed font-medium"></p></div>';
    html += '</div></div>';

    container.innerHTML = html;

    var btn = document.getElementById('nr-btn');
    if (btn) {
      btn.onclick = function() {
        var name = (document.getElementById('nr-name').value || '').trim();
        if (!name) {
          showToast('আপনার নাম লিখুন!', '⚠️');
          return;
        }
        var year = document.getElementById('nr-year').value || '2000';
        var luckyNum = ((name.length * 3 + parseInt(year, 10)) % 9) + 1;
        var colors = ['নীল', 'সবুজ', 'সাদা', 'বেগুনি', 'গোলাপি', 'সোনালি', 'আসমানী'];
        var luckyColor = colors[name.length % colors.length];

        document.getElementById('nr-c1').innerText = name + ' নামের মানুষেরা স্বভাবতই দৃঢ়চেতা, আত্মপ্রত্যয়ী ও গভীর চিন্তাশীল। বিপদে শান্ত থেকে সঠিক সিদ্ধান্ত নেওয়ার অসাধারণ ক্ষমতা থাকে।';
        document.getElementById('nr-c2').innerText = 'আপনার সবচেয়ে শুভ সংখ্যা হলো ' + luckyNum + ' এবং শুভ রং হলো ' + luckyColor + '। শুভ দিন: বৃহস্পতিবার ও শুক্রবার।';
        document.getElementById('nr-c3').innerText = 'নেতৃত্বমূলক পেশা, ব্যবসা, প্রযুক্তি ও সৃজনশীল কাজে আপনার সাফল্য সুনিশ্চিত। কঠোর পরিশ্রমে অল্প সময়েই উন্নতি লাভ করবেন।';
        document.getElementById('nr-c4').innerText = 'শান্তিপূর্ণ জীবন, সত্যবাদী মনোভাব এবং আপনজনদের পাশে থাকার অটুট অঙ্গীকার আপনার চরিত্রের মূল ভিত্তি।';

        document.getElementById('nr-res').classList.remove('hidden');
        showToast('নামের ফলাফল উন্মোচিত হয়েছে! 🌟', '🔮');
      };
    }
  }

  // ===========================================================================
  // MODULE 11: Daily Hishab Tracker (ডেইলি হিসাব ট্র্যাকার)
  // ===========================================================================
  function initDailyHishabModule() {
    var container = document.getElementById('mosafa-hishab-container');
    if (!container) return;

    var items = JSON.parse(localStorage.getItem('mosafa_hishab_items') || '[]');

    function saveAndRender() {
      localStorage.setItem('mosafa_hishab_items', JSON.stringify(items));
      render();
    }

    function render() {
      var income = 0;
      var expense = 0;
      items.forEach(function(it) {
        if (it.type === 'income') income += it.amount;
        else expense += it.amount;
      });
      var balance = income - expense;

      var html = '<div class="max-w-2xl mx-auto space-y-6">';
      html += '<div class="rounded-3xl bg-gradient-to-br from-emerald-600 to-teal-800 text-white p-6 sm:p-8 shadow-md text-center">';
      html += '<h2 class="text-2xl font-black">Daily Hishab (ডেইলি হিসাব ট্র্যাকার)</h2>';
      html += '<p class="text-xs text-emerald-100 mt-1">প্রতিদিনের আয় ও ব্যয় হিসাব রাখুন সহজে ও নিরাপদে।</p>';
      html += '</div>';

      // Summary Cards
      html += '<div class="grid grid-cols-3 gap-3 text-center">';
      html += '<div class="p-4 rounded-2xl bg-white border border-slate-200 shadow-xs"><span class="text-[11px] text-slate-500 font-bold block">মোট আয়</span><span class="text-lg font-black text-emerald-600">৳' + income + '</span></div>';
      html += '<div class="p-4 rounded-2xl bg-white border border-slate-200 shadow-xs"><span class="text-[11px] text-slate-500 font-bold block">মোট ব্যয়</span><span class="text-lg font-black text-rose-600">৳' + expense + '</span></div>';
      html += '<div class="p-4 rounded-2xl bg-white border border-slate-200 shadow-xs"><span class="text-[11px] text-slate-500 font-bold block">অবশিষ্ট ব্যালেন্স</span><span class="text-lg font-black text-slate-900">৳' + balance + '</span></div>';
      html += '</div>';

      // Entry Form
      html += '<div class="bg-white rounded-3xl p-5 border border-slate-200 shadow-xs">';
      html += '<h3 class="text-sm font-bold text-slate-800 mb-3">নতুন এন্ট্রি যোগ করুন</h3>';
      html += '<div class="grid grid-cols-1 sm:grid-cols-4 gap-2 mb-3">';
      html += '<div class="sm:col-span-2"><input type="text" id="dh-desc" placeholder="বিবরণ (যেমন: বেতন, বাজার, চা...)" class="w-full px-3 py-2 rounded-xl border border-slate-300 text-xs font-bold" /></div>';
      html += '<div><input type="number" id="dh-amount" placeholder="পরিমাণ (৳)" class="w-full px-3 py-2 rounded-xl border border-slate-300 text-xs font-bold" /></div>';
      html += '<div><select id="dh-type" class="w-full px-3 py-2 rounded-xl border border-slate-300 text-xs font-bold"><option value="expense">ব্যয় (-)</option><option value="income">আয় (+)</option></select></div>';
      html += '</div>';
      html += '<button type="button" id="dh-add-btn" class="w-full py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white font-black text-xs transition">এন্ট্রি সংরক্ষণ করুন ➕</button>';
      html += '</div>';

      // Items list
      html += '<div class="bg-white rounded-3xl p-5 border border-slate-200 shadow-xs">';
      html += '<div class="flex items-center justify-between mb-3"><h4 class="text-sm font-bold text-slate-800">লেনদেন তালিকা (' + items.length + ')</h4>';
      if (items.length > 0) html += '<button type="button" id="dh-clear-btn" class="text-xs text-rose-600 hover:underline font-bold">সকল মুছুন 🗑️</button>';
      html += '</div>';

      if (items.length === 0) {
        html += '<p class="text-xs text-slate-400 text-center py-6">এখনো কোনো এন্ট্রি যোগ করা হয়নি।</p>';
      } else {
        html += '<div class="space-y-2">';
        items.forEach(function(it, idx) {
          var isInc = it.type === 'income';
          html += '<div class="flex items-center justify-between p-3 rounded-xl border border-slate-100 bg-slate-50 text-xs font-bold">';
          html += '<div class="flex items-center gap-2"><span class="' + (isInc ? 'text-emerald-600' : 'text-rose-600') + '">' + (isInc ? '⬆️' : '⬇️') + '</span><span>' + it.desc + '</span></div>';
          html += '<div class="flex items-center gap-3"><span class="' + (isInc ? 'text-emerald-700 font-black' : 'text-rose-700 font-black') + '">' + (isInc ? '+' : '-') + '৳' + it.amount + '</span><button type="button" class="dh-del-btn text-slate-400 hover:text-rose-600 text-sm font-bold" data-idx="' + idx + '">×</button></div>';
          html += '</div>';
        });
        html += '</div>';
      }
      html += '</div></div>';

      container.innerHTML = html;

      var addBtn = document.getElementById('dh-add-btn');
      if (addBtn) {
        addBtn.onclick = function() {
          var desc = (document.getElementById('dh-desc').value || '').trim();
          var amt = parseFloat(document.getElementById('dh-amount').value);
          var type = document.getElementById('dh-type').value;
          if (!desc || !amt || amt <= 0) {
            showToast('সঠিক বিবরণ ও টাকার পরিমাণ দিন!', '⚠️');
            return;
          }
          items.unshift({ desc: desc, amount: amt, type: type, date: new Date().toLocaleDateString('bn-BD') });
          saveAndRender();
          showToast('এন্ট্রি সফলভাবে যোগ হয়েছে! ৳', '✅');
        };
      }

      var clearBtn = document.getElementById('dh-clear-btn');
      if (clearBtn) {
        clearBtn.onclick = function() {
          if (confirm('আপনি কি নিশ্চিত যে সকল হিসাব মুছে ফেলতে চান?')) {
            items = [];
            saveAndRender();
            showToast('সকল হিসাব মুছে ফেলা হয়েছে!', '🗑️');
          }
        };
      }

      var delBtns = document.querySelectorAll('.dh-del-btn');
      delBtns.forEach(function(b) {
        b.onclick = function() {
          var idx = parseInt(b.getAttribute('data-idx'), 10);
          items.splice(idx, 1);
          saveAndRender();
        };
      });
    }

    render();
  }

  // ===========================================================================
  // MODULE 12: MoSaFa Life Receipt (জীবন হিসাব রশিদ)
  // ===========================================================================
  function initLifeReceiptModule() {
    var container = document.getElementById('mosafa-receipt-container');
    if (!container) return;

    var html = '<div class="max-w-md mx-auto space-y-4">';
    html += '<div class="bg-white rounded-3xl p-6 border border-slate-200 shadow-md text-center">';
    html += '<h2 class="text-2xl font-black text-slate-900">MoSaFa Life Receipt</h2>';
    html += '<p class="text-xs text-slate-500 mt-1 mb-5">জীবনের ঘুম, কাজ ও মোবাইল ব্যবহারের ডিজিটাল ক্যাশ মেমো রশিদ তৈরি করুন।</p>';
    html += '<div class="mb-4 text-left"><label class="block text-xs font-bold text-slate-700 mb-1">আপনার জন্মতারিখ দিন</label><input type="date" id="lr-bday" class="w-full px-4 py-2.5 rounded-xl border border-slate-300 text-xs font-bold" /></div>';
    html += '<button type="button" id="lr-btn" class="w-full py-3 rounded-2xl bg-indigo-600 hover:bg-indigo-700 text-white font-black text-xs sm:text-sm shadow-md transition">রশিদ তৈরি করুন 🧾</button>';
    html += '</div>';

    html += '<div id="lr-receipt-card" class="bg-amber-50/70 border-2 border-dashed border-amber-300 rounded-2xl p-6 font-mono text-xs text-slate-800 shadow-sm hidden space-y-3">';
    html += '<div class="text-center border-b border-amber-200 pb-2"><h3 class="font-black text-sm tracking-widest uppercase">THE MOSAFA LIFE RECEIPT</h3><p class="text-[10px] text-slate-500">DIGITAL MEMO & TIME BREAKDOWN</p></div>';
    html += '<div id="lr-body" class="space-y-1.5 pt-2"></div>';
    html += '<div class="border-t border-amber-200 pt-3 text-center text-[10px] text-slate-500">সময় অমূল্য, প্রতিটি মুহূর্তের সদ্ব্যবহার করুন! ❤️</div>';
    html += '</div></div>';

    container.innerHTML = html;

    var btn = document.getElementById('lr-btn');
    if (btn) {
      btn.onclick = function() {
        var val = document.getElementById('lr-bday').value;
        if (!val) {
          showToast('জন্মতারিখ নির্বাচন করুন!', '⚠️');
          return;
        }
        var bday = new Date(val);
        var now = new Date();
        var totalDays = Math.max(1, Math.floor((now - bday) / (1000 * 60 * 60 * 24)));
        var totalHours = totalDays * 24;

        var sleepHours = Math.round(totalHours * 0.33);
        var screenHours = Math.round(totalHours * 0.18);
        var eatHours = Math.round(totalHours * 0.08);
        var workHours = Math.round(totalHours * 0.22);
        var freeHours = totalHours - sleepHours - screenHours - eatHours - workHours;

        var bodyHtml = '';
        bodyHtml += '<div class="flex justify-between font-bold"><span>অতিক্রান্ত মোট বয়স:</span><span>' + Math.floor(totalDays / 365) + ' বছর (' + totalDays + ' দিন)</span></div>';
        bodyHtml += '<div class="flex justify-between"><span>ঘুমের সময় (~৮ ঘণ্টা):</span><span>' + Math.round(sleepHours / 24) + ' দিন</span></div>';
        bodyHtml += '<div class="flex justify-between"><span>মোবাইল ও স্ক্রিনটাইম:</span><span>' + Math.round(screenHours / 24) + ' দিন</span></div>';
        bodyHtml += '<div class="flex justify-between"><span>খাবার ও আহারের সময়:</span><span>' + Math.round(eatHours / 24) + ' দিন</span></div>';
        bodyHtml += '<div class="flex justify-between"><span>কাজ / পড়াশোনা:</span><span>' + Math.round(workHours / 24) + ' দিন</span></div>';
        bodyHtml += '<div class="flex justify-between border-t border-amber-200 pt-1 font-bold text-indigo-700"><span>বাকি অবসর ও জীবন:</span><span>' + Math.round(freeHours / 24) + ' দিন</span></div>';

        document.getElementById('lr-body').innerHTML = bodyHtml;
        document.getElementById('lr-receipt-card').classList.remove('hidden');
        showToast('রশিদ তৈরি হয়েছে! 🧾', '✨');
      };
    }
  }

  // ===========================================================================
  // MODULE 13: MoSaFa Poster Studio (পোস্টার স্টুডিও)
  // ===========================================================================
  function initPosterStudioModule() {
    var container = document.getElementById('mosafa-poster-container');
    if (!container) return;

    var html = '<div class="max-w-2xl mx-auto space-y-6">';
    html += '<div class="bg-white rounded-3xl p-6 border border-slate-200 shadow-md text-center">';
    html += '<h2 class="text-2xl font-black text-slate-900">MoSaFa Poster Studio</h2>';
    html += '<p class="text-xs text-slate-500 mt-1 mb-5">নিউজ পোস্টার, উক্তি বা ব্যানার কার্ড তৈরি করুন সহজে।</p>';
    html += '<div class="space-y-3 text-left mb-4">';
    html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">শিরোনাম / ব্রেকিং নিউজ</label><input type="text" id="ps-title" value="আজকের বিশেষ সংবাদ ও প্রেরণা" class="w-full px-4 py-2.5 rounded-xl border border-slate-300 text-xs font-bold" /></div>';
    html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">মূল বক্তব্য / বিবরণ</label><textarea id="ps-body" rows="3" class="w-full px-4 py-2.5 rounded-xl border border-slate-300 text-xs font-medium">সফলতা একদিনে আসে না, কিন্তু প্রতিদিনের ছোট ছোট চেষ্টাই একদিন বড় সাফল্যে রূপ নেয়।</textarea></div>';
    html += '<div class="grid grid-cols-2 gap-2"><div><label class="block text-xs font-bold text-slate-700 mb-1">লেখকের নাম / উৎস</label><input type="text" id="ps-author" value="The MoSaFa Studio" class="w-full px-3 py-2 rounded-xl border border-slate-300 text-xs font-bold" /></div><div><label class="block text-xs font-bold text-slate-700 mb-1">ট্যাগ / ক্যাটাগরি</label><input type="text" id="ps-tag" value="অনুপ্রেরণা" class="w-full px-3 py-2 rounded-xl border border-slate-300 text-xs font-bold" /></div></div>';
    html += '</div>';
    html += '<button type="button" id="ps-render-btn" class="w-full py-2.5 rounded-xl bg-rose-600 hover:bg-rose-700 text-white font-black text-xs transition">পোস্টার আপডেট করুন 🎨</button>';
    html += '</div>';

    // Live Card Preview
    html += '<div id="ps-card" class="rounded-3xl p-8 bg-gradient-to-tr from-slate-900 via-rose-950 to-indigo-950 text-white shadow-xl space-y-4 text-center border border-white/10">';
    html += '<span id="ps-tag-disp" class="inline-block px-3 py-1 rounded-full bg-rose-600 text-white font-extrabold text-[10px] uppercase tracking-wider">অনুপ্রেরণা</span>';
    html += '<h3 id="ps-title-disp" class="text-xl sm:text-2xl font-black text-rose-100 leading-tight">আজকের বিশেষ সংবাদ ও প্রেরণা</h3>';
    html += '<p id="ps-body-disp" class="text-xs sm:text-sm text-slate-300 leading-relaxed max-w-lg mx-auto font-medium">সফলতা একদিনে আসে না, কিন্তু প্রতিদিনের ছোট ছোট চেষ্টাই একদিন বড় সাফল্যে রূপ নেয়।</p>';
    html += '<div class="pt-4 border-t border-white/10 flex items-center justify-between text-[11px] text-slate-400 font-bold"><span id="ps-author-disp">The MoSaFa Studio</span><span>The MoSaFa</span></div>';
    html += '</div></div>';

    container.innerHTML = html;

    var btn = document.getElementById('ps-render-btn');
    if (btn) {
      btn.onclick = function() {
        document.getElementById('ps-title-disp').innerText = document.getElementById('ps-title').value || '';
        document.getElementById('ps-body-disp').innerText = document.getElementById('ps-body').value || '';
        document.getElementById('ps-author-disp').innerText = document.getElementById('ps-author').value || '';
        document.getElementById('ps-tag-disp').innerText = document.getElementById('ps-tag').value || '';
        showToast('পোস্টার সফলভাবে আপডেট হয়েছে! 🎨', '✨');
      };
    }
  }

  // ===========================================================================
