    var MILESTONES = [
      { year: 'শৈশব', title: 'জন্ম ও সোনালী দিনগুলো', desc: 'গ্রাম বা শহরের নির্মল শৈশব, কাদা-মাটি ও বন্ধুদের সাথে খেলাধুলো।' },
      { year: 'প্রথম ফোন', title: 'নকিয়া বা সিম্ফনি বাটন ফোন', desc: 'প্রথম স্নেক গেম খেলা, এফএম রেডিও ও মেমোরি কার্ডে গান শোনার নস্টালজিয়া।' },
      { year: 'স্মার্টফোন যুগ', title: 'প্রথম অ্যান্ড্রয়েড স্মার্টফোন', desc: 'ফেসবুক, ইউটিউব ও সেলফি তোলার নতুন অভিজ্ঞতা।' },
      { year: 'বর্তমান', title: 'বর্তমান ডিজিটাল জীবন', desc: 'অনলাইন ক্যারিয়ার, পড়ালেখা ও ভবিষ্যৎ স্বপ্নের পথে যাত্রা।' }
    ];

    var html = '<div class="max-w-xl mx-auto space-y-6">';
    html += '<div class="bg-white rounded-3xl p-6 border border-slate-200 shadow-md text-center">';
    html += '<h2 class="text-2xl font-black text-slate-900">Life Journey (জীবন ও ফোন জার্নি)</h2>';
    html += '<p class="text-xs text-slate-500 mt-1">জীবনের মাইলফলক ও প্রযুক্তিগত বিবর্তনের স্মৃতি টাইমলাইন।</p>';
    html += '</div>';

    html += '<div class="relative border-l-2 border-cyan-400 ml-4 pl-6 space-y-6">';
    MILESTONES.forEach(function(m) {
      html += '<div class="relative bg-white p-4 rounded-2xl border border-slate-200 shadow-xs">';
      html += '<div class="absolute -left-9 top-4 w-6 h-6 rounded-full bg-cyan-500 border-4 border-white shadow-xs"></div>';
      html += '<span class="text-[10px] font-black text-cyan-600 uppercase">' + m.year + '</span>';
      html += '<h4 class="text-sm font-bold text-slate-900 mt-0.5">' + m.title + '</h4>';
      html += '<p class="text-xs text-slate-600 mt-1">' + m.desc + '</p>';
      html += '</div>';
    });
    html += '</div></div>';

    container.innerHTML = html;
  }

  // ===========================================================================
