    html += '<div><label class="block text-[11px] font-bold text-slate-600 mb-1">দাদী / নানীর নাম</label><input type="text" id="ft-grandma" value="দাদী" class="w-full px-3 py-2 rounded-xl border border-slate-300 text-xs font-bold" /></div>';
    html += '<div><label class="block text-[11px] font-bold text-slate-600 mb-1">বাবার নাম</label><input type="text" id="ft-dad" value="বাবা" class="w-full px-3 py-2 rounded-xl border border-slate-300 text-xs font-bold" /></div>';
    html += '<div><label class="block text-[11px] font-bold text-slate-600 mb-1">মায়ের নাম</label><input type="text" id="ft-mom" value="মা" class="w-full px-3 py-2 rounded-xl border border-slate-300 text-xs font-bold" /></div>';
    html += '<div class="col-span-2"><label class="block text-[11px] font-bold text-slate-600 mb-1">আপনার ও ভাই-বোনের নাম</label><input type="text" id="ft-me" value="আমি ও ভাই-বোন" class="w-full px-3 py-2 rounded-xl border border-slate-300 text-xs font-bold" /></div>';
