    html += '<div class="inline-flex gap-4"><div class="px-4 py-2 bg-white rounded-xl border border-emerald-300 shadow-xs font-bold text-xs" id="disp-grandpa">দাদা</div><div class="px-4 py-2 bg-white rounded-xl border border-emerald-300 shadow-xs font-bold text-xs" id="disp-grandma">দাদী</div></div>';
    html += '<div class="text-emerald-500 font-black text-lg">↓</div>';
    html += '<div class="inline-flex gap-4"><div class="px-4 py-2 bg-white rounded-xl border border-emerald-300 shadow-xs font-bold text-xs" id="disp-dad">বাবা</div><div class="px-4 py-2 bg-white rounded-xl border border-emerald-300 shadow-xs font-bold text-xs" id="disp-mom">মা</div></div>';
    html += '<div class="text-emerald-500 font-black text-lg">↓</div>';
    html += '<div><div class="inline-block px-5 py-2.5 bg-emerald-600 text-white rounded-xl shadow-md font-bold text-xs" id="disp-me">আমি ও ভাই-বোন</div></div>';
