        document.getElementById('disp-dad').innerText = document.getElementById('ft-dad').value || 'বাবা';
        document.getElementById('disp-mom').innerText = document.getElementById('ft-mom').value || 'মা';
        document.getElementById('disp-me').innerText = document.getElementById('ft-me').value || 'আমি ও ভাই-বোন';
