  // ===========================================================================
  // MODULE 16: Random Picker Wheel (সিদ্ধান্ত চাকা)
  // ===========================================================================
  function initRandomPickerModule() {
    var container = document.getElementById('mosafa-picker-container');
    if (!container) return;

    var html = '<div class="max-w-md mx-auto bg-white rounded-3xl p-6 sm:p-8 border border-slate-200/90 shadow-md text-center space-y-4">';
    html += '<h2 class="text-2xl font-black text-slate-900">Random Picker Wheel</h2>';
    html += '<p class="text-xs text-slate-500">যেকোনো পছন্দের তালিকা থেকে শতভাগ নিরপেক্ষ সিদ্ধান্ত নিন।</p>';
    html += '<div class="text-left"><label class="block text-xs font-bold text-slate-700 mb-1">বিকল্পগুলো কমা (,) দিয়ে আলাদা করুন</label><textarea id="rp-input" rows="3" class="w-full p-3 rounded-xl border border-slate-300 text-xs font-bold">কাচ্চি বিরিয়ানি, পিৎজা, চাইনিজ, খিচুড়ি, বার্গার</textarea></div>';
    html += '<div class="py-6 flex justify-center"><div id="rp-display" class="w-32 h-32 rounded-full bg-gradient-to-tr from-purple-500 to-pink-500 border-4 border-white shadow-xl flex items-center justify-center text-white font-black text-sm p-3 transition-transform duration-700">🎡 চাকা</div></div>';
    html += '<button type="button" id="rp-spin-btn" class="w-full py-3 rounded-2xl bg-purple-600 hover:bg-purple-700 text-white font-black text-xs sm:text-sm shadow-md transition">চাকা ঘোরান 🎡</button>';
    html += '<div id="rp-winner" class="text-base font-black text-purple-700 hidden"></div>';
    html += '</div>';

    container.innerHTML = html;

    var btn = document.getElementById('rp-spin-btn');
    var disp = document.getElementById('rp-display');
    var win = document.getElementById('rp-winner');

    if (btn) {
      btn.onclick = function() {
        var raw = (document.getElementById('rp-input').value || '').trim();
        var items = raw.split(/[,，\n]+/).map(function(s) { return s.trim(); }).filter(Boolean);
        if (items.length < 2) {
          showToast('কমপক্ষে ২টি বিকল্প লিখুন!', '⚠️');
          return;
        }

        btn.disabled = true;
        disp.style.transform = 'rotate(1080deg) scale(1.1)';

        setTimeout(function() {
          var chosen = items[Math.floor(Math.random() * items.length)];
          disp.style.transform = 'rotate(0deg) scale(1)';
          disp.innerText = chosen;
          win.innerText = 'নির্বাচিত ফলাফল: ' + chosen + ' 🎉';
          win.classList.remove('hidden');
          btn.disabled = false;
          if (window.confetti) window.confetti({ particleCount: 60, spread: 70 });
          showToast('সিদ্ধান্ত পাওয়া গেছে: ' + chosen + ' 🎡', '🎉');
        }, 700);
      };
    }
  }

  // ===========================================================================
  // MODULE 17: Bangla Riddles & Quiz Challenge (ধাঁধা ও কুইজ)
  // ===========================================================================
  function initBanglaQuizModule() {
    var container = document.getElementById('mosafa-quiz-container');
    if (!container) return;

    var QUIZ = [
      { q: 'গাছে ধরে ফল, কিন্তু খায় না মানুষ, কাটলে বের হয় পানি। কী সেটা?', opts: ['ডাব/নারকেল', 'তরমুজ', 'বেল', 'আনারস'], ans: 0 },
      { q: 'লাল বরণ রূপ তার, খেতে বড় ঝাল, তরকারি রাঁধতে লাগে সব কাল। কী সেটা?', opts: ['মরিচ', 'টমেটো', 'গাজর', 'বিট'], ans: 0 },
      { q: 'আট পা যার, জল না হলে মরে তার, জাল বুনে বাস করে কার?', opts: ['মাকড়সা', 'মাছি', 'কাঁকড়া', 'অক্টোপাস'], ans: 0 }
    ];

    var cur = 0;
    var score = 0;

    function renderQuestion() {
      if (cur >= QUIZ.length) {
        var finHtml = '<div class="max-w-md mx-auto bg-white rounded-3xl p-8 border border-slate-200 text-center space-y-4 shadow-md">';
        finHtml += '<div class="text-5xl">🏆</div>';
        finHtml += '<h2 class="text-2xl font-black text-slate-900">কুইজ সম্পন্ন হয়েছে!</h2>';
        finHtml += '<p class="text-lg font-black text-amber-600">আপনার স্কোর: ' + score + ' / ' + QUIZ.length + '</p>';
        finHtml += '<button type="button" id="bq-restart" class="w-full py-2.5 rounded-xl bg-amber-500 text-white font-bold text-xs">আবার খেলুন 🔄</button>';
        finHtml += '</div>';
        container.innerHTML = finHtml;
        var rBtn = document.getElementById('bq-restart');
        if (rBtn) {
          rBtn.onclick = function() {
            cur = 0;
            score = 0;
            renderQuestion();
          };
        }
        return;
      }

      var item = QUIZ[cur];
      var html = '<div class="max-w-md mx-auto bg-white rounded-3xl p-6 sm:p-8 border border-slate-200 shadow-md space-y-4">';
      html += '<div class="flex justify-between items-center text-xs font-bold text-slate-500"><span>প্রশ্ন ' + (cur + 1) + ' / ' + QUIZ.length + '</span><span>স্কোর: ' + score + '</span></div>';
      html += '<h3 class="text-base font-black text-slate-900 leading-snug">“' + item.q + '”</h3>';
      html += '<div class="space-y-2 pt-2">';
      item.opts.forEach(function(opt, idx) {
        html += '<button type="button" class="bq-opt w-full p-3 rounded-xl border border-slate-200 hover:bg-amber-50 hover:border-amber-300 text-left text-xs font-bold transition flex items-center justify-between" data-idx="' + idx + '"><span>' + opt + '</span><span>➔</span></button>';
      });
      html += '</div></div>';

      container.innerHTML = html;

      var opts = document.querySelectorAll('.bq-opt');
      opts.forEach(function(btn) {
        btn.onclick = function() {
          var sel = parseInt(btn.getAttribute('data-idx'), 10);
          if (sel === item.ans) {
            score++;
            showToast('সঠিক উত্তর! 🎉', '✅');
          } else {
            showToast('ভুল উত্তর! সঠিক: ' + item.opts[item.ans], '❌');
          }
          cur++;
          setTimeout(renderQuestion, 600);
        };
      });
    }

    renderQuestion();
  }

  // ===========================================================================
  // MODULE 18: MoSaFa Personality Reveal (ব্যক্তিত্ব উন্মোচন)
  // ===========================================================================
  function initPersonalityModule() {
