    html += '<div class="w-16 h-16 rounded-full bg-violet-50 text-violet-600 mx-auto flex items-center justify-center text-3xl mb-1 shadow-inner">🌟</div>';
    html += '<h2 class="text-2xl font-black text-slate-900">ব্যক্তিত্ব উন্মোচন টেস্ট</h2>';
    html += '<p class="text-xs text-slate-500">আপনার স্বভাব ও চিন্তা অনুযায়ী আপনার প্রধান চারিত্রিক শক্তি উন্মোচন করুন।</p>';
    html += '<div class="space-y-3 text-left pt-2">';
    html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">অবসরে আপনার বেশি পছন্দ:</label><select id="pr-q1" class="w-full px-3 py-2 rounded-xl border border-slate-300 text-xs font-bold"><option value="1">বই পড়া বা নতুন কিছু শেখা</option><option value="2">বন্ধুদের সাথে আড্ডা ও ভ্রমণ</option><option value="3">নীরবে নিজের পরিকল্পনা সাজানো</option></select></div>';
    html += '<div><label class="block text-xs font-bold text-slate-700 mb-1">বিপদের সময় আপনার প্রতিক্রিয়া:</label><select id="pr-q2" class="w-full px-3 py-2 rounded-xl border border-slate-300 text-xs font-bold"><option value="1">শান্ত থেকে সমাধান খোঁজা</option><option value="2">সবাইকে উৎসাহ ও ভরসা দেওয়া</option><option value="3">দ্রুত বাস্তবসম্মত সিদ্ধান্ত নেওয়া</option></select></div>';
    html += '</div>';
    html += '<button type="button" id="pr-btn" class="w-full py-3 rounded-2xl bg-violet-600 hover:bg-violet-700 text-white font-black text-xs sm:text-sm shadow-md transition">ব্যক্তিত্ব উন্মোচন করুন 🌟</button>';
    html += '<div id="pr-res" class="mt-4 p-5 rounded-2xl bg-violet-50 border border-violet-200 hidden text-left space-y-2">';
    html += '<h4 class="text-sm font-black text-violet-900" id="pr-title"></h4>';
    html += '<p class="text-xs text-slate-700 leading-relaxed font-medium" id="pr-desc"></p>';
    html += '</div></div>';

    container.innerHTML = html;

    var btn = document.getElementById('pr-btn');
    if (btn) {
      btn.onclick = function() {
        var res = document.getElementById('pr-res');
        res.classList.remove('hidden');
        document.getElementById('pr-title').innerText = 'আপনার ব্যক্তিত্ব: দূরদর্শী চিন্তাবিদ ও সহনশীল নেতা (The Visionary Leader)';
        document.getElementById('pr-desc').innerText = 'আপনি একজন গভীর অনুভূতিশীল, বিবেকবান ও নির্ভরযোগ্য ব্যক্তি। আপনার কথা ও কাজের মধ্যে চমৎকার ভারসাম্য রয়েছে এবং চারপাশের মানুষ আপনার উপস্থিতিতে নিরাপদ বোধ করে।';
        if (window.confetti) window.confetti({ particleCount: 50, spread: 60 });
        showToast('ব্যক্তিত্বের রেজাল্ট উন্মোচিত হয়েছে! 🌟', '✅');
      };
    }
  }

  // ===========================================================================
  // 6. Main App Controller
  // ===========================================================================
  function renderApp() {
    var toolParam = getQueryParam('tool');
    if (toolParam) {
      renderTool(toolParam);
    } else {
      renderHub();
    }
  }

  // Intercept links to enable SPA router
  document.addEventListener('click', function(e) {
    var target = e.target.closest('a');
    if (target && target.getAttribute('href') && target.getAttribute('href').startsWith('?')) {
      e.preventDefault();
      var href = target.getAttribute('href');
      var params = new URLSearchParams(href);
      var tool = params.get('tool');
      navigateTo(tool);
    }
  });

  // Initial Run
  renderApp();

})();
